import react from '@vitejs/plugin-react'
import { defineConfig } from 'vite'

// https://vite.dev/config/
export default defineConfig({
  plugins: [react()],
})

// ============================================================
// Data model types — §3 of the spec
// ============================================================

export type Id = string;

export interface Settings {
  currency_code: string;
  labour_rate_per_hour: number;
  overhead_pct: number;          // fraction, e.g. 0.25
  target_margin: number;         // fraction of selling price, e.g. 0.30
  packaging_allowance_pct: number;
  topper_price: number;
  cake_batches_per_kg: number;
  frosting_batches_per_kg: number;
  filling_grams_per_kg: number;
  fondant_ingredient_id: Id | null;
  edible_print_item_id: Id | null;
  cake_box_item_id: Id | null;
  mdf_board_item_id: Id | null;
  standard_board_item_id: Id | null;
  wallpaper_item_id: Id | null;
  price_rounding_step?: number;
}

export interface PriceHistoryEntry {
  date: string;          // ISO date string e.g. '2026-10-07'
  pack_quantity: number;
  pack_price: number;
  note?: string;
}

export interface Ingredient {
  id: Id;
  name: string;
  unit_type: 'g' | 'piece';
  pack_quantity: number;
  pack_price: number;
  piece_weight_g?: number | null;
  grams_per_tsp?: number | null;
  notes?: string;
  price_history?: PriceHistoryEntry[];
}

export interface PackagingItem {
  id: Id;
  name: string;
  price: number;
  notes?: string;
}

export type LineUnit = 'g' | 'piece' | 'tsp';

export interface RecipeLine {
  ingredient_id: Id | null;
  quantity: number;
  unit: LineUnit;
  exclude_from_weight?: boolean;
  piece_weight_g_override?: number | null;
  label?: string;
}

export type RecipeKind = 'cake' | 'frosting_filling' | 'batch_product' | 'other';

export interface Recipe {
  id: Id;
  name: string;
  kind: RecipeKind;
  lines: RecipeLine[];
  weight_adjustment_g: number;
  notes?: string;
}

export type FlavourCostModel =
  | { type: 'recipe'; cake_recipe_id: Id; frosting_recipe_id: Id }
  | { type: 'average'; of: Id[] };

export interface Flavour {
  id: Id;
  name: string;
  cost_model: FlavourCostModel;
  addon_cost_per_kg: number;
}

export type FillingSource =
  | { type: 'recipe'; recipe_id: Id }
  | { type: 'ingredient'; ingredient_id: Id };

export interface Filling {
  id: Id;
  name: string;
  source: FillingSource;
}

export interface BatchProduct {
  id: Id;
  name: string;
  recipe_id: Id;
  pieces_mode: 'by_weight' | 'fixed';
  piece_weight_g?: number;
  fixed_pieces?: number;
  labour_hours_per_batch: number;
  components: { recipe_id: Id; grams: number }[];
  box_id: Id | null;
  pieces_per_box: number;
  show_each_including_box: boolean;
}

export type AssembledComponent =
  | { type: 'cake_recipe_grams'; recipe_id: Id; grams: number }
  | { type: 'recipe_per_gram'; recipe_id: Id; grams: number }
  | { type: 'ingredient_grams'; ingredient_id: Id; grams: number };

export interface AssembledProduct {
  id: Id;
  name: string;
  components: AssembledComponent[];
  labour_hours_per_batch: number;
  pieces_per_batch: number;
  box_id: Id | null;
  pieces_per_box: number;
}

export interface TierInput {
  size_kg: number;
  flavour_id?: Id | null;
  filling_id?: Id | null;
}

export interface DecorationInput {
  fondant_kg: number;
  prints: number;
  flowers: number;
  toppers: number;
  time_hours: number;
  others: number;
  delivery: number;
  discount?: number; // money amount; capped to available profit; 0/undefined = no discount
}

export interface QuoteInput {
  tiers: TierInput[];  // exactly 6 slots
  decoration: DecorationInput;
}

export interface SizeGuideEntry {
  label: string;
  kg: number;
  servings: number;
}

export interface SavedQuote {
  id: Id;
  name: string;
  created_at: string;
  updated_at?: string;
  input: QuoteInput;
  result_snapshot: unknown;
  notes?: string;
}

export interface Customer {
  id: Id;
  name: string;
  phone?: string;
  email?: string;
  address?: string;
  notes?: string;
}

export type OrderStatus = 'Draft' | 'Confirmed' | 'Delivered' | 'Cancelled';

export interface Order {
  id: Id;
  customer_id: Id | null;
  quote_id: Id | null;
  order_date?: string;
  due_date?: string;
  status: OrderStatus;
  notes?: string;
}

// ============================================================
// Engine result types
// ============================================================

export type WarningCode =
  | 'W_UNPRICED_INGREDIENT'
  | 'W_ZERO_WEIGHT_RECIPE'
  | 'W_ZERO_PIECES'
  | 'W_TIER_NO_FLAVOUR'
  | 'W_TIER_NO_FILLING'
  | 'W_TIER_NO_SIZE'
  | 'W_UNKNOWN_FLAVOUR'
  | 'W_UNKNOWN_FILLING'
  | 'W_NO_TIME_HOURS'
  | 'W_NO_LABOUR_HOURS'
  | 'W_ADDON_ZERO'
  | 'W_ROLE_NOT_SET'
  | 'W_DISCOUNT_CAPPED'
  | 'W_ORDER_WITHOUT_QUOTE'
  | 'W_ORDER_PAST_DUE';

export interface Warning {
  code: WarningCode;
  context: string;  // human-readable detail
  path?: string;    // e.g. "recipes[2].lines[0]"
}

export interface AuditStep {
  label: string;
  formula: string;
  value: number;
  children?: AuditStep[];
}

export interface RecipeResult {
  raw: number;
  cwo: number;
  weight: number;
  per_gram_cwo: number;
  cake_cost_per_kg: number;
  frosting_cost_per_kg_cake: number;
  warnings: Warning[];
  audit: AuditStep[];
}

export interface FlavourResult {
  base: number;
  price_per_kg: number;
  warnings: Warning[];
  audit: AuditStep[];
}

export interface FillingResult {
  cost_per_kg: number;
  warnings: Warning[];
  audit: AuditStep[];
}

export interface BatchProductResult {
  pieces: number;
  raw_cost_per_piece: number;
  unit_cost: number;
  each_including_box: number;
  each_excluding_box: number;
  box_price: number;
  headline_each: number;
  suggested_headline_each?: number;
  warnings: Warning[];
  audit: AuditStep[];
}

export interface AssembledProductResult {
  unit_cost: number;
  labour_piece: number;
  box_piece: number;
  price_each: number;
  suggested_price_each?: number;
  warnings: Warning[];
  audit: AuditStep[];
}

export interface QuoteResult {
  tier_cost: number;
  tiers_used: number;
  decoration_sum: number;
  fondant: number;
  print: number;
  flowers: number;
  topper: number;
  time: number;
  others: number;
  delivery: number;
  overhead: number;
  packaging: number;
  total_cost: number;
  profit: number;
  discount: number;           // effective discount (after cap), always >= 0
  discount_capped: boolean;   // true when input exceeded available profit
  total_price: number;        // total_price = total_cost + profit - discount
  suggested_price?: number;   // display-only suggested rounded price
  margin_check: number;       // effective margin after discount
  tier_details: { flavour_part: number; filling_part: number }[];
  warnings: Warning[];
  audit: AuditStep[];
}

export interface EngineResult {
  recipes: Record<Id, RecipeResult>;
  flavours: Record<Id, FlavourResult>;
  fillings: Record<Id, FillingResult>;
  batch_products: Record<Id, BatchProductResult>;
  assembled_products: Record<Id, AssembledProductResult>;
  quote: QuoteResult | null;
  all_warnings: Warning[];
}

// ============================================================
// Full data store type
// ============================================================

export interface AppData {
  settings: Settings;
  ingredients: Ingredient[];
  packaging_items: PackagingItem[];
  recipes: Recipe[];
  flavours: Flavour[];
  fillings: Filling[];
  batch_products: BatchProduct[];
  assembled_products: AssembledProduct[];
  size_guide: SizeGuideEntry[];
  saved_quotes: SavedQuote[];
  customers: Customer[];
  orders: Order[];
}

export const DEFAULT_SETTINGS: Settings = {
  currency_code: 'BDT',
  labour_rate_per_hour: 400,
  overhead_pct: 0.25,
  target_margin: 0.30,
  packaging_allowance_pct: 0.20,
  topper_price: 350,
  cake_batches_per_kg: 1,
  frosting_batches_per_kg: 1.25,
  filling_grams_per_kg: 150,
  fondant_ingredient_id: null,
  edible_print_item_id: null,
  cake_box_item_id: null,
  mdf_board_item_id: null,
  standard_board_item_id: null,
  wallpaper_item_id: null,
  price_rounding_step: 0,
};

export const DEFAULT_SIZE_GUIDE: SizeGuideEntry[] = [
  { label: '5"', kg: 0.7, servings: 10 },
  { label: '6"', kg: 1, servings: 15 },
  { label: '7"', kg: 1.5, servings: 20 },
  { label: '8"', kg: 2, servings: 30 },
  { label: '9"', kg: 2.5, servings: 38 },
  { label: '10"', kg: 3, servings: 45 },
  { label: '11"', kg: 3.5, servings: 52 },
  { label: '12"', kg: 4.5, servings: 67 },
];

export const EMPTY_APP_DATA: AppData = {
  settings: { ...DEFAULT_SETTINGS },
  ingredients: [],
  packaging_items: [],
  recipes: [],
  flavours: [],
  fillings: [],
  batch_products: [],
  assembled_products: [],
  size_guide: [...DEFAULT_SIZE_GUIDE],
  saved_quotes: [],
  customers: [],
  orders: [],
};

/**
 * Shared utility helpers for OvenCost Pro.
 * No imports from React, the store, IndexedDB, window, document, or fetch.
 */

/**
 * Generate a time-based unique ID with an optional prefix.
 * e.g. generateId('cust') → 'cust_1728289012345_abc12'
 */
export function generateId(prefix = 'id'): string {
  const ts = Date.now().toString(36);
  const rand = Math.random().toString(36).slice(2, 7);
  return `${prefix}_${ts}_${rand}`;
}

import { useState } from 'react';

interface ToggleProps {
  checked: boolean;
  onChange: (v: boolean) => void;
  label?: string;
  id?: string;
}

export function Toggle({ checked, onChange, label, id }: ToggleProps) {
  return (
    <label className="toggle" htmlFor={id} style={{ cursor: 'pointer', fontSize: 13, color: 'var(--text-secondary)' }}>
      <input
        type="checkbox"
        id={id}
        checked={checked}
        onChange={e => onChange(e.target.checked)}
        style={{ position: 'absolute', opacity: 0 }}
      />
      <span
        style={{
          display: 'inline-block',
          width: 36, height: 20,
          background: checked ? 'var(--accent)' : 'var(--bg-input)',
          border: `1px solid ${checked ? 'var(--accent)' : 'var(--border)'}`,
          borderRadius: 20,
          position: 'relative',
          flexShrink: 0,
          transition: 'background 120ms, border-color 120ms',
        }}
      >
        <span
          style={{
            position: 'absolute',
            top: 2, left: 2,
            width: 14, height: 14,
            background: 'white',
            borderRadius: '50%',
            transform: checked ? 'translateX(16px)' : 'translateX(0)',
            transition: 'transform 120ms',
          }}
        />
      </span>
      {label && <span>{label}</span>}
    </label>
  );
}

interface NumberInputProps {
  value: number;
  onChange: (v: number) => void;
  min?: number;
  max?: number;
  step?: number;
  placeholder?: string;
  className?: string;
  id?: string;
  disabled?: boolean;
  allowNeg?: boolean;
}

export function NumberInput({ value, onChange, min, max, step, placeholder, className = '', id, disabled, allowNeg }: NumberInputProps) {
  const [raw, setRaw] = useState<string | null>(null);
  const effectiveMin = min !== undefined ? min : (allowNeg ? undefined : 0);

  return (
    <input
      type="number"
      id={id}
      className={`input ${className}`}
      value={raw !== null ? raw : (value === 0 ? '' : value)}
      min={effectiveMin}
      max={max}
      step={step}
      placeholder={placeholder ?? '0'}
      disabled={disabled}
      onChange={e => {
        setRaw(e.target.value);
        const n = parseFloat(e.target.value);
        if (!isNaN(n) && isFinite(n)) onChange(n);
        else if (e.target.value === '' || e.target.value === '-') onChange(0);
      }}
      onBlur={() => setRaw(null)}
    />
  );
}

interface ConfirmDialogProps {
  message: string;
  onConfirm: () => void;
  onCancel: () => void;
  confirmLabel?: string;
  danger?: boolean;
}

export function ConfirmDialog({ message, onConfirm, onCancel, confirmLabel = 'Confirm', danger = false }: ConfirmDialogProps) {
  return (
    <div className="modal-backdrop" onClick={onCancel}>
      <div className="modal" style={{ maxWidth: 380 }} onClick={e => e.stopPropagation()}>
        <div className="modal-header"><h2 className="modal-title">Confirm</h2></div>
        <div className="modal-body"><p style={{ color: 'var(--text-secondary)', fontSize: 14 }}>{message}</p></div>
        <div className="modal-footer">
          <button className="btn btn-ghost" onClick={onCancel}>Cancel</button>
          <button className={`btn ${danger ? 'btn-danger' : 'btn-primary'}`} onClick={onConfirm}>{confirmLabel}</button>
        </div>
      </div>
    </div>
  );
}

interface SearchBarProps {
  value: string;
  onChange: (v: string) => void;
  placeholder?: string;
}

export function SearchBar({ value, onChange, placeholder = 'Search…' }: SearchBarProps) {
  return (
    <div className="search-bar" style={{ maxWidth: 280 }}>
      <span className="search-bar-icon">🔍</span>
      <input
        className="input"
        style={{ paddingLeft: 32 }}
        value={value}
        onChange={e => onChange(e.target.value)}
        placeholder={placeholder}
      />
    </div>
  );
}

import { useState } from 'react';
import { StoreProvider, useStore } from './store/store';
import { Layout } from './ui/Layout';
import { QuotePage } from './ui/pages/QuotePage';
import { IngredientsPage } from './ui/pages/IngredientsPage';
import { PackagingPage } from './ui/pages/PackagingPage';
import { RecipesPage } from './ui/pages/RecipesPage';
import { FlavoursPage } from './ui/pages/FlavoursPage';
import { ProductsPage } from './ui/pages/ProductsPage';
import { SettingsPage } from './ui/pages/SettingsPage';
import { DataHealthPage } from './ui/pages/DataHealthPage';
import { ImportExportPage } from './ui/pages/ImportExportPage';
import { SavedQuotesPage } from './ui/pages/SavedQuotesPage';
import { CustomersPage } from './ui/pages/CustomersPage';
import { OrdersPage } from './ui/pages/OrdersPage';

function AppContent() {
  const { state } = useStore();
  const [currentPage, setCurrentPage] = useState('quote');

  if (state.loading) {
    return (
      <div style={{
        display: 'flex',
        minHeight: '100vh',
        alignItems: 'center',
        justifyContent: 'center',
        background: 'var(--bg-base)',
        color: 'var(--text-secondary)',
        flexDirection: 'column',
        gap: 16
      }}>
        <div style={{ fontSize: 40, animation: 'spin 1s linear infinite' }}>🎂</div>
        <div style={{ fontSize: 16, fontWeight: 500 }}>Loading OvenCost Pro database...</div>
      </div>
    );
  }

  const renderPage = () => {
    switch (currentPage) {
      case 'quote':
        return <QuotePage />;
      case 'saved_quotes':
        return <SavedQuotesPage onNavigate={setCurrentPage} />;
      case 'customers':
        return <CustomersPage />;
      case 'orders':
        return <OrdersPage onNavigate={setCurrentPage} />;
      case 'ingredients':
        return <IngredientsPage />;
      case 'packaging':
        return <PackagingPage />;
      case 'recipes':
        return <RecipesPage />;
      case 'flavours':
        return <FlavoursPage />;
      case 'products':
        return <ProductsPage />;
      case 'settings':
        return <SettingsPage />;
      case 'health':
        return <DataHealthPage onNavigate={setCurrentPage} />;
      case 'import_export':
        return <ImportExportPage />;
      default:
        return <QuotePage />;
    }
  };

  return (
    <Layout currentPage={currentPage} onNavigate={setCurrentPage}>
      {renderPage()}
    </Layout>
  );
}

export default function App() {
  return (
    <StoreProvider>
      <AppContent />
    </StoreProvider>
  );
}

/**
 * Pure calculation engine — implements §4 of the spec exactly.
 * No UI, storage or network access. All arithmetic uses decimal.js.
 */
import Decimal from 'decimal.js';
import type {
  AppData,
  Ingredient,
  PackagingItem,
  Recipe,
  RecipeLine,
  Flavour,
  Filling,
  BatchProduct,
  AssembledProduct,
  QuoteInput,
  Settings,
  Id,
  EngineResult,
  RecipeResult,
  FlavourResult,
  FillingResult,
  BatchProductResult,
  AssembledProductResult,
  QuoteResult,
  Warning,
  WarningCode,
  AuditStep,
} from './types';

Decimal.set({ precision: 28, toExpNeg: -28, toExpPos: 28 });

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

const D = (v: number | string | Decimal): Decimal => new Decimal(v);

function toNum(d: Decimal): number {
  return d.toNumber();
}

export function roundPrice(price: Decimal | number, step?: number): number {
  if (!step || step <= 0) {
    return typeof price === 'number' ? price : toNum(price);
  }
  const dPrice = typeof price === 'number' ? D(price) : price;
  const dStep = D(step);
  return toNum(dPrice.div(dStep).round().mul(dStep));
}

function warn(
  warnings: Warning[],
  code: WarningCode,
  context: string,
  path?: string
): void {
  warnings.push({ code, context, path });
}

function step(label: string, formula: string, value: Decimal | number, children?: AuditStep[]): AuditStep {
  return {
    label,
    formula,
    value: typeof value === 'number' ? value : toNum(value),
    children,
  };
}

// ---------------------------------------------------------------------------
// §4.1 Ingredient price
// ---------------------------------------------------------------------------

function ppu(ing: Ingredient): Decimal {
  // price per gram (unit_type g) or per piece (unit_type piece)
  if (!ing.pack_quantity || ing.pack_quantity <= 0) return D(0);
  return D(ing.pack_price).div(D(ing.pack_quantity));
}

function unpriced(ing: Ingredient): boolean {
  return !(ing.pack_quantity > 0 && ing.pack_price > 0);
}

// ---------------------------------------------------------------------------
// §4.2 Recipe line cost / weight
// ---------------------------------------------------------------------------

function lineCost(
  line: RecipeLine,
  ingMap: Map<Id, Ingredient>,
  warnings: Warning[],
  path: string
): Decimal {
  if (line.ingredient_id === null) return D(0);
  const ing = ingMap.get(line.ingredient_id);
  if (!ing) {
    warn(warnings, 'W_UNPRICED_INGREDIENT', `Ingredient ${line.ingredient_id} not found`, path);
    return D(0);
  }
  if (unpriced(ing)) {
    warn(warnings, 'W_UNPRICED_INGREDIENT', `Ingredient "${ing.name}" is unpriced`, path);
    return D(0);
  }
  const p = ppu(ing);
  if (line.unit === 'tsp') {
    const gramsPerTsp = ing.grams_per_tsp ?? 0;
    return D(line.quantity).mul(D(gramsPerTsp)).mul(p);
  }
  return D(line.quantity).mul(p);
}

function lineWeight(line: RecipeLine, ingMap: Map<Id, Ingredient>): Decimal {
  if (line.exclude_from_weight) return D(0);
  if (line.unit === 'g') return D(line.quantity);
  if (line.unit === 'piece') {
    const ing = line.ingredient_id ? ingMap.get(line.ingredient_id) : null;
    const pieceW = line.piece_weight_g_override ?? ing?.piece_weight_g ?? 0;
    return D(line.quantity).mul(D(pieceW));
  }
  if (line.unit === 'tsp') {
    const ing = line.ingredient_id ? ingMap.get(line.ingredient_id) : null;
    const gramsPerTsp = ing?.grams_per_tsp ?? 0;
    return D(line.quantity).mul(D(gramsPerTsp));
  }
  return D(0);
}

// ---------------------------------------------------------------------------
// §4.3 Recipe
// ---------------------------------------------------------------------------

function computeRecipe(
  recipe: Recipe,
  ingMap: Map<Id, Ingredient>,
  settings: Settings,
  warnings: Warning[],
  multiplier: number = 1
): RecipeResult {
  const OH = D(settings.overhead_pct);
  const recipeWarnings: Warning[] = [];
  const lineAudit: AuditStep[] = [];

  let rawCost = D(0);
  let weightG = D(0);

  for (let i = 0; i < recipe.lines.length; i++) {
    const line = recipe.lines[i];
    const path = `recipe[${recipe.id}].lines[${i}]`;
    const lc = lineCost(line, ingMap, recipeWarnings, path);
    const lw = lineWeight(line, ingMap);
    rawCost = rawCost.add(lc);
    weightG = weightG.add(lw);

    const ingName = line.ingredient_id
      ? ingMap.get(line.ingredient_id)?.name ?? line.ingredient_id
      : '(free item)';
    lineAudit.push(step(
      `Line: ${ingName}`,
      `${line.quantity} ${line.unit}`,
      lc,
    ));
  }
  weightG = weightG.add(D(recipe.weight_adjustment_g));

  if (multiplier !== 1) {
    rawCost = rawCost.mul(D(multiplier));
    weightG = weightG.mul(D(multiplier));
  }

  const cwo = rawCost.mul(D(1).add(OH));
  const perGramCwo = weightG.gt(0) ? cwo.div(weightG) : D(0);
  const cakeCostPerKg = cwo.mul(D(settings.cake_batches_per_kg));
  const frostingCostPerKgCake = cwo.mul(D(settings.frosting_batches_per_kg));

  warnings.push(...recipeWarnings);

  const audit: AuditStep[] = [
    step('Raw cost (Σ line costs)', 'Σ line_cost(l)', rawCost, lineAudit),
    step('Cost with overhead (cwo)', 'raw_cost × (1 + OH)', cwo),
    step('Batch weight', 'Σ line_weight(l) + weight_adjustment_g', weightG),
    step('Per-gram cwo', 'cwo / weight_g', perGramCwo),
    step('Cake cost/kg', 'cwo × cake_batches_per_kg', cakeCostPerKg),
    step('Frosting cost/kg cake', 'cwo × frosting_batches_per_kg', frostingCostPerKgCake),
  ];

  return {
    raw: toNum(rawCost),
    cwo: toNum(cwo),
    weight: toNum(weightG),
    per_gram_cwo: toNum(perGramCwo),
    cake_cost_per_kg: toNum(cakeCostPerKg),
    frosting_cost_per_kg_cake: toNum(frostingCostPerKgCake),
    warnings: recipeWarnings,
    audit,
  };
}

// ---------------------------------------------------------------------------
// §4.5 Flavour price per kg of cake
// ---------------------------------------------------------------------------

function computeFlavourBase(
  flavour: Flavour,
  flavourMap: Map<Id, Flavour>,
  recipeResults: Map<Id, RecipeResult>,
  warnings: Warning[],
  visited: Set<Id> = new Set()
): Decimal {
  if (visited.has(flavour.id)) {
    warn(warnings, 'W_UNKNOWN_FLAVOUR', `Circular average reference in flavour "${flavour.name}"`, `flavour[${flavour.id}]`);
    return D(0);
  }
  visited.add(flavour.id);

  if (flavour.cost_model.type === 'recipe') {
    const cakeRec = recipeResults.get(flavour.cost_model.cake_recipe_id);
    const frostRec = recipeResults.get(flavour.cost_model.frosting_recipe_id);
    const cakePart = cakeRec ? D(cakeRec.cake_cost_per_kg) : D(0);
    const frostPart = frostRec ? D(frostRec.frosting_cost_per_kg_cake) : D(0);
    return cakePart.add(frostPart);
  } else {
    // average of base prices
    const refs = flavour.cost_model.of;
    if (refs.length === 0) return D(0);
    let sum = D(0);
    let count = 0;
    for (const refId of refs) {
      const ref = flavourMap.get(refId);
      if (!ref) {
        warn(warnings, 'W_UNKNOWN_FLAVOUR', `Averaged flavour id "${refId}" not found`, `flavour[${flavour.id}]`);
        continue;
      }
      const newVisited = new Set(visited);
      sum = sum.add(computeFlavourBase(ref, flavourMap, recipeResults, warnings, newVisited));
      count++;
    }
    return count > 0 ? sum.div(D(count)) : D(0);
  }
}

function computeFlavour(
  flavour: Flavour,
  flavourMap: Map<Id, Flavour>,
  recipeResults: Map<Id, RecipeResult>,
  settings: Settings,
  warnings: Warning[]
): FlavourResult {
  const OH = D(settings.overhead_pct);
  const flavourWarnings: Warning[] = [];

  if (flavour.addon_cost_per_kg === 0) {
    warn(flavourWarnings, 'W_ADDON_ZERO', `Flavour "${flavour.name}" has zero addon_cost_per_kg`, `flavour[${flavour.id}]`);
  }

  const base = computeFlavourBase(flavour, flavourMap, recipeResults, flavourWarnings);
  const addonWithOH = D(flavour.addon_cost_per_kg).mul(D(1).add(OH));
  const pricePerKg = base.add(addonWithOH);

  warnings.push(...flavourWarnings);

  const audit: AuditStep[] = [
    step('Base price/kg', 'cake_cost_per_kg + frosting_cost_per_kg_cake (or avg)', base),
    step('Addon with overhead', 'addon_cost_per_kg × (1 + OH)', addonWithOH),
    step('Flavour price/kg', 'base + addon_with_overhead', pricePerKg),
  ];

  return {
    base: toNum(base),
    price_per_kg: toNum(pricePerKg),
    warnings: flavourWarnings,
    audit,
  };
}

// ---------------------------------------------------------------------------
// §4.6 Filling cost per kg of cake
// ---------------------------------------------------------------------------

function computeFilling(
  filling: Filling,
  ingMap: Map<Id, Ingredient>,
  recipeResults: Map<Id, RecipeResult>,
  settings: Settings,
  warnings: Warning[]
): FillingResult {
  const OH = D(settings.overhead_pct);
  const fillGrams = D(settings.filling_grams_per_kg);
  const fillingWarnings: Warning[] = [];
  let costPerKg = D(0);
  const audit: AuditStep[] = [];

  if (filling.source.type === 'recipe') {
    const recRes = recipeResults.get(filling.source.recipe_id);
    if (!recRes) {
      warn(fillingWarnings, 'W_ZERO_WEIGHT_RECIPE', `Filling recipe "${filling.source.recipe_id}" not found`, `filling[${filling.id}]`);
    } else {
      if (recRes.weight === 0) {
        warn(fillingWarnings, 'W_ZERO_WEIGHT_RECIPE', `Filling recipe has zero weight`, `filling[${filling.id}]`);
      }
      const pgCwo = D(recRes.per_gram_cwo);
      costPerKg = pgCwo.mul(fillGrams);
      audit.push(step('per_gram_cwo', 'cwo / weight_g', pgCwo));
      audit.push(step('cost/kg cake', 'per_gram_cwo × filling_grams_per_kg', costPerKg));
    }
  } else {
    const ing = ingMap.get(filling.source.ingredient_id);
    if (!ing) {
      warn(fillingWarnings, 'W_UNPRICED_INGREDIENT', `Filling ingredient "${filling.source.ingredient_id}" not found`, `filling[${filling.id}]`);
    } else {
      if (unpriced(ing)) {
        warn(fillingWarnings, 'W_UNPRICED_INGREDIENT', `Filling ingredient "${ing.name}" is unpriced`, `filling[${filling.id}]`);
      }
      const p = ppu(ing);
      costPerKg = p.mul(fillGrams).mul(D(1).add(OH));
      audit.push(step('ppu', 'pack_price / pack_quantity', p));
      audit.push(step('cost/kg cake', 'ppu × filling_grams_per_kg × (1+OH)', costPerKg));
    }
  }

  warnings.push(...fillingWarnings);
  return { cost_per_kg: toNum(costPerKg), warnings: fillingWarnings, audit };
}

// ---------------------------------------------------------------------------
// §4.8 Batch product
// ---------------------------------------------------------------------------

function computeBatchProduct(
  product: BatchProduct,
  recipeResults: Map<Id, RecipeResult>,
  _recipeMap: Map<Id, Recipe>,
  packMap: Map<Id, PackagingItem>,
  settings: Settings,
  warnings: Warning[]
): BatchProductResult {
  const OH = D(settings.overhead_pct);
  const M = D(settings.target_margin);
  const LAB = D(settings.labour_rate_per_hour);
  const prodWarnings: Warning[] = [];
  const audit: AuditStep[] = [];

  const r = recipeResults.get(product.recipe_id);
  const rawCost = r ? D(r.raw) : D(0);
  const weightG = r ? D(r.weight) : D(0);

  let pieces: Decimal;
  if (product.pieces_mode === 'by_weight') {
    const pw = D(product.piece_weight_g ?? 0);
    if (pw.lte(0)) {
      warn(prodWarnings, 'W_ZERO_PIECES', `Product "${product.id}" piece_weight_g is 0`, `batch_product[${product.id}]`);
      pieces = D(0);
    } else {
      pieces = weightG.div(pw);
    }
    audit.push(step('Pieces (by weight)', 'weight_g / piece_weight_g', pieces));
  } else {
    pieces = D(product.fixed_pieces ?? 0);
    if (pieces.lte(0)) {
      warn(prodWarnings, 'W_ZERO_PIECES', `Product "${product.id}" fixed_pieces is 0`, `batch_product[${product.id}]`);
    }
    audit.push(step('Pieces (fixed)', 'fixed_pieces', pieces));
  }

  if (product.labour_hours_per_batch === 0) {
    warn(prodWarnings, 'W_NO_LABOUR_HOURS', `Product "${product.id}" has zero labour hours`, `batch_product[${product.id}]`);
  }

  const labour = D(product.labour_hours_per_batch).mul(LAB);
  const baseUnitCost = pieces.gt(0)
    ? rawCost.add(labour).mul(D(1).add(OH)).div(pieces)
    : D(0);

  // Components (already contain overhead, do NOT add again)
  let componentsCost = D(0);
  for (const comp of product.components) {
    const cr = recipeResults.get(comp.recipe_id);
    if (!cr) continue;
    const pgCwo = D(cr.per_gram_cwo);
    componentsCost = componentsCost.add(pgCwo.mul(D(comp.grams)));
  }

  const unitCost = baseUnitCost.add(componentsCost);

  const boxItem = product.box_id ? packMap.get(product.box_id) : null;
  const boxPrice = boxItem ? D(boxItem.price) : D(0);
  const ppb = D(product.pieces_per_box > 0 ? product.pieces_per_box : 1);

  const eachInclBox = D(1).minus(M).gt(0)
    ? unitCost.add(boxPrice.div(ppb)).div(D(1).minus(M))
    : D(0);
  const eachExclBox = D(1).minus(M).gt(0)
    ? unitCost.div(D(1).minus(M))
    : D(0);
  const boxPriceResult = D(1).minus(M).gt(0)
    ? unitCost.mul(ppb).add(boxPrice).div(D(1).minus(M))
    : D(0);
  const headlineEach = product.show_each_including_box ? eachInclBox : eachExclBox;

  const rawCostPerPiece = pieces.gt(0) ? rawCost.div(pieces) : D(0);

  audit.push(
    step('Labour', 'labour_hours × LAB', labour),
    step('Base unit cost', '(raw_cost + labour) × (1+OH) / pieces', baseUnitCost),
    step('Components cost/piece', 'Σ per_gram_cwo × grams', componentsCost),
    step('Unit cost', 'base_unit_cost + components_cost', unitCost),
    step('Each incl. box', '(unit_cost + box/ppb) / (1-M)', eachInclBox),
    step('Each excl. box', 'unit_cost / (1-M)', eachExclBox),
    step('Box price (full box)', '(unit_cost × ppb + box) / (1-M)', boxPriceResult),
  );

  const roundingStep = settings.price_rounding_step;
  const suggestedHeadline = roundingStep && roundingStep > 0
    ? roundPrice(headlineEach, roundingStep)
    : undefined;

  if (suggestedHeadline !== undefined) {
    audit.push(step('Suggested headline each (display only)', `round(${toNum(headlineEach).toFixed(2)}, nearest ${roundingStep})`, suggestedHeadline));
  }

  warnings.push(...prodWarnings);

  return {
    pieces: toNum(pieces),
    raw_cost_per_piece: toNum(rawCostPerPiece),
    unit_cost: toNum(unitCost),
    each_including_box: toNum(eachInclBox),
    each_excluding_box: toNum(eachExclBox),
    box_price: toNum(boxPriceResult),
    headline_each: toNum(headlineEach),
    suggested_headline_each: suggestedHeadline,
    warnings: prodWarnings,
    audit,
  };
}

// ---------------------------------------------------------------------------
// §4.9 Assembled product
// ---------------------------------------------------------------------------

function computeAssembledProduct(
  product: AssembledProduct,
  recipeResults: Map<Id, RecipeResult>,
  ingMap: Map<Id, Ingredient>,
  packMap: Map<Id, PackagingItem>,
  settings: Settings,
  warnings: Warning[]
): AssembledProductResult {
  const OH = D(settings.overhead_pct);
  const M = D(settings.target_margin);
  const LAB = D(settings.labour_rate_per_hour);
  const prodWarnings: Warning[] = [];
  const audit: AuditStep[] = [];

  let unitCost = D(0);
  for (const comp of product.components) {
    let compCost = D(0);
    if (comp.type === 'cake_recipe_grams') {
      const rr = recipeResults.get(comp.recipe_id);
      if (!rr) continue;
      // cake_cost_per_gram = cwo * cake_batches_per_kg / 1000
      const cakeCostPerGram = D(rr.cwo).mul(D(settings.cake_batches_per_kg)).div(D(1000));
      compCost = cakeCostPerGram.mul(D(comp.grams));
      audit.push(step(`Cake (${comp.recipe_id}) ${comp.grams}g`, 'cake_cost_per_gram × grams', compCost));
    } else if (comp.type === 'recipe_per_gram') {
      const rr = recipeResults.get(comp.recipe_id);
      if (!rr) continue;
      compCost = D(rr.per_gram_cwo).mul(D(comp.grams));
      audit.push(step(`Recipe (${comp.recipe_id}) ${comp.grams}g`, 'per_gram_cwo × grams', compCost));
    } else if (comp.type === 'ingredient_grams') {
      const ing = ingMap.get(comp.ingredient_id);
      if (!ing) continue;
      if (unpriced(ing)) {
        warn(prodWarnings, 'W_UNPRICED_INGREDIENT', `Ingredient "${ing.name}" unpriced in assembled product`, `assembled[${product.id}]`);
      }
      compCost = ppu(ing).mul(D(comp.grams)).mul(D(1).add(OH));
      audit.push(step(`Ingredient (${ing.name}) ${comp.grams}g`, 'ppu × grams × (1+OH)', compCost));
    }
    unitCost = unitCost.add(compCost);
  }

  if (product.labour_hours_per_batch === 0) {
    warn(prodWarnings, 'W_NO_LABOUR_HOURS', `Assembled product "${product.id}" has zero labour hours`, `assembled[${product.id}]`);
  }

  const piecesPerBatch = D(product.pieces_per_batch > 0 ? product.pieces_per_batch : 1);
  const labourPiece = D(product.labour_hours_per_batch).mul(LAB).mul(D(1).add(OH)).div(piecesPerBatch);

  const boxItem = product.box_id ? packMap.get(product.box_id) : null;
  const boxPrice = boxItem ? D(boxItem.price) : D(0);
  const ppb = D(product.pieces_per_box > 0 ? product.pieces_per_box : 1);
  const boxPiece = boxPrice.div(ppb);

  const priceEach = D(1).minus(M).gt(0)
    ? unitCost.add(labourPiece).add(boxPiece).div(D(1).minus(M))
    : D(0);

  audit.push(
    step('Unit cost (components)', 'Σ component_cost(c)', unitCost),
    step('Labour per piece', 'labour_hours × LAB × (1+OH) / pieces_per_batch', labourPiece),
    step('Box per piece', 'box_price / pieces_per_box', boxPiece),
    step('Price each', '(unit_cost + labour + box) / (1-M)', priceEach),
  );

  const roundingStep = settings.price_rounding_step;
  const suggestedPriceEach = roundingStep && roundingStep > 0
    ? roundPrice(priceEach, roundingStep)
    : undefined;

  if (suggestedPriceEach !== undefined) {
    audit.push(step('Suggested price each (display only)', `round(${toNum(priceEach).toFixed(2)}, nearest ${roundingStep})`, suggestedPriceEach));
  }

  warnings.push(...prodWarnings);

  return {
    unit_cost: toNum(unitCost),
    labour_piece: toNum(labourPiece),
    box_piece: toNum(boxPiece),
    price_each: toNum(priceEach),
    suggested_price_each: suggestedPriceEach,
    warnings: prodWarnings,
    audit,
  };
}

// ---------------------------------------------------------------------------
// §4.7 Cake quote
// ---------------------------------------------------------------------------

function computeQuote(
  quoteInput: QuoteInput,
  flavourResults: Map<Id, FlavourResult>,
  fillingResults: Map<Id, FillingResult>,
  packMap: Map<Id, PackagingItem>,
  ingMap: Map<Id, Ingredient>,
  _flavourMap: Map<Id, Flavour>,
  _fillingMap: Map<Id, Filling>,
  settings: Settings,
  warnings: Warning[]
): QuoteResult | null {
  // Gate: tier 1 must have size_kg > 0
  const tiers = quoteInput.tiers;
  if (!tiers[0] || tiers[0].size_kg <= 0) return null;

  const OH = D(settings.overhead_pct);
  const M = D(settings.target_margin);
  const LAB = D(settings.labour_rate_per_hour);
  const quoteWarnings: Warning[] = [];
  const audit: AuditStep[] = [];

  let tierCostTotal = D(0);
  let tiersUsed = 0;
  const tierDetails: { flavour_part: number; filling_part: number }[] = [];

  for (let i = 0; i < 6; i++) {
    const tier = tiers[i] ?? { size_kg: 0 };
    const sizeKg = D(tier.size_kg ?? 0);

    if (sizeKg.lte(0)) {
      // Check if flavour/filling set without size
      if (tier.flavour_id || tier.filling_id) {
        warn(quoteWarnings, 'W_TIER_NO_SIZE', `Tier ${i + 1} has flavour/filling but size_kg is 0`, `tiers[${i}]`);
      }
      tierDetails.push({ flavour_part: 0, filling_part: 0 });
      continue;
    }

    tiersUsed++;

    // Flavour
    let flavourPart = D(0);
    if (!tier.flavour_id) {
      warn(quoteWarnings, 'W_TIER_NO_FLAVOUR', `Tier ${i + 1} is missing a flavour`, `tiers[${i}]`);
    } else {
      const fl = flavourResults.get(tier.flavour_id);
      if (!fl) {
        warn(quoteWarnings, 'W_UNKNOWN_FLAVOUR', `Tier ${i + 1} flavour not found`, `tiers[${i}]`);
      } else {
        flavourPart = sizeKg.mul(D(fl.price_per_kg));
      }
    }

    // Filling
    let fillingPart = D(0);
    if (!tier.filling_id) {
      warn(quoteWarnings, 'W_TIER_NO_FILLING', `Tier ${i + 1} is missing a filling`, `tiers[${i}]`);
    } else {
      const fi = fillingResults.get(tier.filling_id);
      if (!fi) {
        warn(quoteWarnings, 'W_UNKNOWN_FILLING', `Tier ${i + 1} filling not found`, `tiers[${i}]`);
      } else {
        fillingPart = sizeKg.mul(D(fi.cost_per_kg));
      }
    }

    tierCostTotal = tierCostTotal.add(flavourPart).add(fillingPart);
    tierDetails.push({ flavour_part: toNum(flavourPart), filling_part: toNum(fillingPart) });
    audit.push(step(`Tier ${i + 1} (${tier.size_kg}kg)`, 'flavour_part + filling_part', flavourPart.add(fillingPart)));
  }

  const dec = quoteInput.decoration;

  // fondant: quote quantity is kg; ppu is per gram, so multiply by 1000
  let fondant = D(0);
  if (dec.fondant_kg > 0) {
    if (!settings.fondant_ingredient_id) {
      warn(quoteWarnings, 'W_ROLE_NOT_SET', 'Fondant ingredient role not set in settings', 'settings.fondant_ingredient_id');
    } else {
      const fondantIng = ingMap.get(settings.fondant_ingredient_id);
      if (fondantIng) {
        fondant = D(dec.fondant_kg).mul(ppu(fondantIng)).mul(D(1000));
      }
    }
  }

  let printCost = D(0);
  if (dec.prints > 0) {
    if (!settings.edible_print_item_id) {
      warn(quoteWarnings, 'W_ROLE_NOT_SET', 'Edible print item role not set in settings', 'settings.edible_print_item_id');
    } else {
      const printItem = packMap.get(settings.edible_print_item_id);
      printCost = printItem ? D(dec.prints).mul(D(printItem.price)) : D(0);
    }
  }

  const flowers = D(dec.flowers);
  const topper = D(dec.toppers).mul(D(settings.topper_price));
  const time = D(dec.time_hours).mul(LAB);
  const others = D(dec.others);
  const delivery = D(dec.delivery);

  if (dec.time_hours === 0) {
    warn(quoteWarnings, 'W_NO_TIME_HOURS', 'Time hours is 0 — labour is free', 'decoration.time_hours');
  }

  const decorationSum = fondant.add(printCost).add(flowers).add(topper).add(time).add(others);
  // overhead on decoration (NOT on delivery, NOT on tiers which already have it via flavour/filling)
  const overhead = decorationSum.mul(OH);

  // packaging
  const cakeBoxItem = settings.cake_box_item_id ? packMap.get(settings.cake_box_item_id) : null;
  const mdfItem = settings.mdf_board_item_id ? packMap.get(settings.mdf_board_item_id) : null;
  const wallpaperItem = settings.wallpaper_item_id ? packMap.get(settings.wallpaper_item_id) : null;
  const stdBoardItem = settings.standard_board_item_id ? packMap.get(settings.standard_board_item_id) : null;

  const cakeBoxPrice = cakeBoxItem ? D(cakeBoxItem.price) : D(0);
  const mdfPrice = mdfItem ? D(mdfItem.price) : D(0);
  const wallpaperPrice = wallpaperItem ? D(wallpaperItem.price) : D(0);
  const stdBoardPrice = stdBoardItem ? D(stdBoardItem.price) : D(0);

  const packagingAllowance = D(settings.packaging_allowance_pct);
  const packagingBase = cakeBoxPrice
    .add(mdfPrice)
    .add(wallpaperPrice)
    .add(stdBoardPrice.mul(D(tiersUsed)));
  const packaging = packagingBase.mul(D(1).add(packagingAllowance));

  const totalCost = tierCostTotal.add(decorationSum).add(delivery).add(overhead).add(packaging);

  // profit = (total_cost - delivery) * M / (1 - M)
  const profitBase = totalCost.minus(delivery);
  const profit = D(1).minus(M).gt(0)
    ? profitBase.mul(M).div(D(1).minus(M))
    : D(0);

  // Discount — comes out of profit only; capped to [0, profit]
  const rawDiscount = D(Math.max(0, dec.discount ?? 0));
  const effectiveDiscount = rawDiscount.gt(profit) ? profit : rawDiscount;
  const discountCapped = rawDiscount.gt(profit) && rawDiscount.gt(0);

  if (discountCapped) {
    warn(quoteWarnings, 'W_DISCOUNT_CAPPED',
      `Discount was capped from ${rawDiscount.toFixed(2)} to ${effectiveDiscount.toFixed(2)} (available profit)`,
      'decoration.discount');
  }

  const totalPrice = totalCost.add(profit).minus(effectiveDiscount);
  const marginCheck = totalPrice.minus(delivery).gt(0)
    ? profit.minus(effectiveDiscount).div(totalPrice.minus(delivery))
    : D(0);

  audit.push(
    step('Tier cost total', 'Σ (flavour_part + filling_part)', tierCostTotal),
    step('Fondant', 'fondant_kg × ppu(fondant) × 1000', fondant),
    step('Edible print', 'prints × price(edible_print)', printCost),
    step('Flowers', 'user amount', flowers),
    step('Topper', 'toppers × topper_price', topper),
    step('Time / Labour', 'time_hours × LAB', time),
    step('Others', 'user amount', others),
    step('Decoration sum', 'fondant+print+flowers+topper+time+others', decorationSum),
    step('Delivery', 'user amount (no profit, no overhead)', delivery),
    step('Overhead on decoration', 'decoration_sum × OH', overhead),
    step('Packaging', '(cake_box + mdf + wallpaper + std_board×tiers_used) × (1+packaging_allowance_pct)', packaging),
    step('Total cost', 'tier_cost + decoration_sum + delivery + overhead + packaging', totalCost),
    step('Profit', '(total_cost - delivery) × M / (1-M)', profit),
    step('Discount', `capped to profit if needed (input: ${toNum(rawDiscount).toFixed(2)})`, effectiveDiscount),
    step('Total price', 'total_cost + profit - discount', totalPrice),
    step('Margin check', 'profit / (total_price - delivery)', marginCheck),
  );

  const roundingStep = settings.price_rounding_step;
  const suggestedPrice = roundingStep && roundingStep > 0
    ? roundPrice(totalPrice, roundingStep)
    : undefined;

  if (suggestedPrice !== undefined) {
    audit.push(step('Suggested price (display only)', `round(${toNum(totalPrice).toFixed(2)}, nearest ${roundingStep})`, suggestedPrice));
  }

  warnings.push(...quoteWarnings);

  return {
    tier_cost: toNum(tierCostTotal),
    tiers_used: tiersUsed,
    decoration_sum: toNum(decorationSum),
    fondant: toNum(fondant),
    print: toNum(printCost),
    flowers: toNum(flowers),
    topper: toNum(topper),
    time: toNum(time),
    others: toNum(others),
    delivery: toNum(delivery),
    overhead: toNum(overhead),
    packaging: toNum(packaging),
    total_cost: toNum(totalCost),
    profit: toNum(profit),
    discount: toNum(effectiveDiscount),
    discount_capped: discountCapped,
    total_price: toNum(totalPrice),
    suggested_price: suggestedPrice,
    margin_check: toNum(marginCheck),
    tier_details: tierDetails,
    warnings: quoteWarnings,
    audit,
  };
}

// ---------------------------------------------------------------------------
// Main compute function
// ---------------------------------------------------------------------------

export function compute(data: AppData, quoteInput?: QuoteInput | null, recipeMultipliers?: Record<Id, number>): EngineResult {
  const { settings, ingredients, packaging_items, recipes, flavours, fillings, batch_products, assembled_products } = data;

  const ingMap = new Map<Id, Ingredient>(ingredients.map(i => [i.id, i]));
  const packMap = new Map<Id, PackagingItem>(packaging_items.map(p => [p.id, p]));
  const recipeMap = new Map<Id, Recipe>(recipes.map(r => [r.id, r]));
  const flavourMap = new Map<Id, Flavour>(flavours.map(f => [f.id, f]));
  const fillingMap = new Map<Id, Filling>(fillings.map(f => [f.id, f]));

  const allWarnings: Warning[] = [];

  // §4.3 Recipes
  const recipeResults = new Map<Id, RecipeResult>();
  for (const recipe of recipes) {
    const mult = recipeMultipliers?.[recipe.id] ?? 1;
    const res = computeRecipe(recipe, ingMap, settings, allWarnings, mult);
    recipeResults.set(recipe.id, res);
  }

  // §4.5 Flavours
  const flavourResults = new Map<Id, FlavourResult>();
  for (const flavour of flavours) {
    const res = computeFlavour(flavour, flavourMap, recipeResults, settings, allWarnings);
    flavourResults.set(flavour.id, res);
  }

  // §4.6 Fillings
  const fillingResults = new Map<Id, FillingResult>();
  for (const filling of fillings) {
    const res = computeFilling(filling, ingMap, recipeResults, settings, allWarnings);
    fillingResults.set(filling.id, res);
  }

  // §4.8 Batch products
  const batchProductResults = new Map<Id, BatchProductResult>();
  for (const product of batch_products) {
    const res = computeBatchProduct(product, recipeResults, recipeMap, packMap, settings, allWarnings);
    batchProductResults.set(product.id, res);
  }

  // §4.9 Assembled products
  const assembledProductResults = new Map<Id, AssembledProductResult>();
  for (const product of assembled_products) {
    const res = computeAssembledProduct(product, recipeResults, ingMap, packMap, settings, allWarnings);
    assembledProductResults.set(product.id, res);
  }

  // §4.7 Quote
  let quote: QuoteResult | null = null;
  if (quoteInput) {
    quote = computeQuote(
      quoteInput,
      flavourResults,
      fillingResults,
      packMap,
      ingMap,
      flavourMap,
      fillingMap,
      settings,
      allWarnings
    );
  }

  // Phase 4: Order data health warnings
  const todayStr = new Date().toISOString().split('T')[0];
  if (data.orders) {
    for (const o of data.orders) {
      if (!o.quote_id) {
        allWarnings.push({
          code: 'W_ORDER_WITHOUT_QUOTE',
          context: `Order has no linked quote`,
          path: `order[${o.id}]`
        });
      }
      if (o.due_date && o.due_date < todayStr && o.status !== 'Delivered' && o.status !== 'Cancelled') {
        allWarnings.push({
          code: 'W_ORDER_PAST_DUE',
          context: `Order is past due (${o.due_date}) but status is ${o.status}`,
          path: `order[${o.id}]`
        });
      }
    }
  }

  return {
    recipes: Object.fromEntries(recipeResults),
    flavours: Object.fromEntries(flavourResults),
    fillings: Object.fromEntries(fillingResults),
    batch_products: Object.fromEntries(batchProductResults),
    assembled_products: Object.fromEntries(assembledProductResults),
    quote,
    all_warnings: allWarnings,
  };
}

/**
 * Import / Export — §6 of the spec.
 * Validation, preview, CSV support, atomic application, blank template.
 */
import type {
  AppData,
  Settings,
  Ingredient,
  PackagingItem,
  Recipe,
  RecipeLine,
  Flavour,
  Filling,
  BatchProduct,
  AssembledProduct,
  SizeGuideEntry,
  SavedQuote,
  Customer,
  Order,
  OrderStatus,
  PriceHistoryEntry,
  Id,
} from '../engine/types';
import { DEFAULT_SETTINGS, DEFAULT_SIZE_GUIDE } from '../engine/types';

const CURRENT_SCHEMA_VERSION = '1.2';
const FORMAT_FIELD = 'bakery-costing-data';
const MAX_FILE_SIZE = 20 * 1024 * 1024; // 20 MB

export interface ImportError {
  path: string;
  message: string;
}

export interface ImportPreview {
  valid: boolean;
  errors: ImportError[];
  warnings: string[];
  counts: {
    settings: boolean;
    ingredients: { add: number; update: number; unchanged: number };
    packaging_items: { add: number; update: number; unchanged: number };
    recipes: { add: number; update: number; unchanged: number };
    flavours: { add: number; update: number; unchanged: number };
    fillings: { add: number; update: number; unchanged: number };
    batch_products: { add: number; update: number; unchanged: number };
    assembled_products: { add: number; update: number; unchanged: number };
    saved_quotes: { add: number; update: number; unchanged: number };
    customers: { add: number; update: number; unchanged: number };
    orders: { add: number; update: number; unchanged: number };
  };
  parsed: Partial<AppData>;
}

// ---------------------------------------------------------------------------
// ID pattern validation
// ---------------------------------------------------------------------------

const ID_PATTERN = /^[a-z0-9_-]{1,64}$/;

function validateId(id: unknown, path: string, errors: ImportError[]): id is string {
  if (typeof id !== 'string' || !ID_PATTERN.test(id)) {
    errors.push({ path, message: `Invalid id: "${id}". Must match ^[a-z0-9_-]{1,64}$` });
    return false;
  }
  return true;
}

function requireNumber(v: unknown, path: string, errors: ImportError[], allowNeg = false): number {
  if (typeof v !== 'number' || !isFinite(v) || (!allowNeg && v < 0)) {
    errors.push({ path, message: `Expected a finite non-negative number, got ${v}` });
    return 0;
  }
  return v;
}

function requireString(v: unknown, path: string, errors: ImportError[]): string {
  if (typeof v !== 'string') {
    errors.push({ path, message: `Expected string, got ${typeof v}` });
    return '';
  }
  return v;
}

// ---------------------------------------------------------------------------
// Validators per entity
// ---------------------------------------------------------------------------

function validateSettings(raw: unknown, errors: ImportError[]): Settings {
  const s = (raw ?? {}) as Record<string, unknown>;
  const out: Settings = { ...DEFAULT_SETTINGS };
  const p = 'settings';
  if (s.currency_code !== undefined) out.currency_code = String(s.currency_code);
  if (s.labour_rate_per_hour !== undefined) out.labour_rate_per_hour = requireNumber(s.labour_rate_per_hour, `${p}.labour_rate_per_hour`, errors);
  if (s.overhead_pct !== undefined) out.overhead_pct = requireNumber(s.overhead_pct, `${p}.overhead_pct`, errors);
  if (s.target_margin !== undefined) {
    const m = requireNumber(s.target_margin, `${p}.target_margin`, errors);
    if (m >= 1) errors.push({ path: `${p}.target_margin`, message: 'target_margin must be < 1' });
    out.target_margin = Math.min(m, 0.9999);
  }
  if (s.packaging_allowance_pct !== undefined) out.packaging_allowance_pct = requireNumber(s.packaging_allowance_pct, `${p}.packaging_allowance_pct`, errors);
  if (s.topper_price !== undefined) out.topper_price = requireNumber(s.topper_price, `${p}.topper_price`, errors);
  if (s.cake_batches_per_kg !== undefined) out.cake_batches_per_kg = requireNumber(s.cake_batches_per_kg, `${p}.cake_batches_per_kg`, errors);
  if (s.frosting_batches_per_kg !== undefined) out.frosting_batches_per_kg = requireNumber(s.frosting_batches_per_kg, `${p}.frosting_batches_per_kg`, errors);
  if (s.filling_grams_per_kg !== undefined) out.filling_grams_per_kg = requireNumber(s.filling_grams_per_kg, `${p}.filling_grams_per_kg`, errors);
  out.fondant_ingredient_id = (s.fondant_ingredient_id as Id | null) ?? null;
  out.edible_print_item_id = (s.edible_print_item_id as Id | null) ?? null;
  out.cake_box_item_id = (s.cake_box_item_id as Id | null) ?? null;
  out.mdf_board_item_id = (s.mdf_board_item_id as Id | null) ?? null;
  out.standard_board_item_id = (s.standard_board_item_id as Id | null) ?? null;
  out.wallpaper_item_id = (s.wallpaper_item_id as Id | null) ?? null;
  if (s.price_rounding_step !== undefined) {
    out.price_rounding_step = requireNumber(s.price_rounding_step, `${p}.price_rounding_step`, errors);
  }
  return out;
}

function validateIngredient(raw: unknown, idx: number, errors: ImportError[]): Ingredient | null {
  const r = (raw ?? {}) as Record<string, unknown>;
  const p = `ingredients[${idx}]`;
  const id = r.id;
  if (!validateId(id, `${p}.id`, errors)) return null;
  const unitType = r.unit_type;
  if (unitType !== 'g' && unitType !== 'piece') {
    errors.push({ path: `${p}.unit_type`, message: `Must be "g" or "piece"` });
    return null;
  }
  return {
    id: id as string,
    name: requireString(r.name, `${p}.name`, errors),
    unit_type: unitType,
    pack_quantity: requireNumber(r.pack_quantity, `${p}.pack_quantity`, errors),
    pack_price: requireNumber(r.pack_price, `${p}.pack_price`, errors),
    piece_weight_g: typeof r.piece_weight_g === 'number' ? r.piece_weight_g : null,
    grams_per_tsp: typeof r.grams_per_tsp === 'number' ? r.grams_per_tsp : null,
    notes: typeof r.notes === 'string' ? r.notes : undefined,
    price_history: Array.isArray(r.price_history)
      ? (r.price_history as unknown[]).map((h): PriceHistoryEntry => {
          const he = (h ?? {}) as Record<string, unknown>;
          return {
            date: typeof he.date === 'string' ? he.date : '',
            pack_quantity: typeof he.pack_quantity === 'number' ? he.pack_quantity : 0,
            pack_price: typeof he.pack_price === 'number' ? he.pack_price : 0,
            note: typeof he.note === 'string' ? he.note : undefined,
          };
        })
      : undefined,
  };
}

function validatePackaging(raw: unknown, idx: number, errors: ImportError[]): PackagingItem | null {
  const r = (raw ?? {}) as Record<string, unknown>;
  const p = `packaging_items[${idx}]`;
  const id = r.id;
  if (!validateId(id, `${p}.id`, errors)) return null;
  return {
    id: id as string,
    name: requireString(r.name, `${p}.name`, errors),
    price: requireNumber(r.price, `${p}.price`, errors),
    notes: typeof r.notes === 'string' ? r.notes : undefined,
  };
}

function validateRecipeLine(raw: unknown, recipeIdx: number, lineIdx: number, errors: ImportError[]): RecipeLine {
  const r = (raw ?? {}) as Record<string, unknown>;
  const p = `recipes[${recipeIdx}].lines[${lineIdx}]`;
  const unit = r.unit;
  if (unit !== 'g' && unit !== 'piece' && unit !== 'tsp') {
    errors.push({ path: `${p}.unit`, message: 'Must be "g", "piece", or "tsp"' });
  }
  return {
    ingredient_id: typeof r.ingredient_id === 'string' ? r.ingredient_id : null,
    quantity: requireNumber(r.quantity, `${p}.quantity`, errors),
    unit: (unit as 'g' | 'piece' | 'tsp') ?? 'g',
    exclude_from_weight: r.exclude_from_weight === true,
    piece_weight_g_override: typeof r.piece_weight_g_override === 'number' ? r.piece_weight_g_override : null,
    label: typeof r.label === 'string' ? r.label : undefined,
  };
}

function validateRecipe(raw: unknown, idx: number, errors: ImportError[]): Recipe | null {
  const r = (raw ?? {}) as Record<string, unknown>;
  const p = `recipes[${idx}]`;
  const id = r.id;
  if (!validateId(id, `${p}.id`, errors)) return null;
  const kind = r.kind;
  if (!['cake', 'frosting_filling', 'batch_product', 'other'].includes(kind as string)) {
    errors.push({ path: `${p}.kind`, message: 'Invalid kind' });
    return null;
  }
  const lines = Array.isArray(r.lines)
    ? r.lines.map((l, li) => validateRecipeLine(l, idx, li, errors))
    : [];
  return {
    id: id as string,
    name: requireString(r.name, `${p}.name`, errors),
    kind: kind as Recipe['kind'],
    lines,
    weight_adjustment_g: typeof r.weight_adjustment_g === 'number' ? r.weight_adjustment_g : 0,
    notes: typeof r.notes === 'string' ? r.notes : undefined,
  };
}

function validateFlavour(raw: unknown, idx: number, errors: ImportError[]): Flavour | null {
  const r = (raw ?? {}) as Record<string, unknown>;
  const p = `flavours[${idx}]`;
  const id = r.id;
  if (!validateId(id, `${p}.id`, errors)) return null;
  const cm = r.cost_model as Record<string, unknown>;
  let costModel: Flavour['cost_model'];
  if (cm?.type === 'recipe') {
    costModel = { type: 'recipe', cake_recipe_id: cm.cake_recipe_id as string, frosting_recipe_id: cm.frosting_recipe_id as string };
  } else if (cm?.type === 'average') {
    costModel = { type: 'average', of: Array.isArray(cm.of) ? cm.of as string[] : [] };
  } else {
    errors.push({ path: `${p}.cost_model.type`, message: 'Must be "recipe" or "average"' });
    return null;
  }
  return {
    id: id as string,
    name: requireString(r.name, `${p}.name`, errors),
    cost_model: costModel,
    addon_cost_per_kg: requireNumber(r.addon_cost_per_kg, `${p}.addon_cost_per_kg`, errors),
  };
}

function validateFilling(raw: unknown, idx: number, errors: ImportError[]): Filling | null {
  const r = (raw ?? {}) as Record<string, unknown>;
  const p = `fillings[${idx}]`;
  const id = r.id;
  if (!validateId(id, `${p}.id`, errors)) return null;
  const src = r.source as Record<string, unknown>;
  let source: Filling['source'];
  if (src?.type === 'recipe') {
    source = { type: 'recipe', recipe_id: src.recipe_id as string };
  } else if (src?.type === 'ingredient') {
    source = { type: 'ingredient', ingredient_id: src.ingredient_id as string };
  } else {
    errors.push({ path: `${p}.source.type`, message: 'Must be "recipe" or "ingredient"' });
    return null;
  }
  return {
    id: id as string,
    name: requireString(r.name, `${p}.name`, errors),
    source,
  };
}

function validateBatchProduct(raw: unknown, idx: number, errors: ImportError[]): BatchProduct | null {
  const r = (raw ?? {}) as Record<string, unknown>;
  const p = `batch_products[${idx}]`;
  const id = r.id;
  if (!validateId(id, `${p}.id`, errors)) return null;
  return {
    id: id as string,
    name: requireString(r.name ?? (id as string), `${p}.name`, errors),
    recipe_id: String(r.recipe_id ?? ''),
    pieces_mode: r.pieces_mode === 'fixed' ? 'fixed' : 'by_weight',
    piece_weight_g: typeof r.piece_weight_g === 'number' ? r.piece_weight_g : undefined,
    fixed_pieces: typeof r.fixed_pieces === 'number' ? r.fixed_pieces : undefined,
    labour_hours_per_batch: requireNumber(r.labour_hours_per_batch, `${p}.labour_hours_per_batch`, errors),
    components: Array.isArray(r.components) ? r.components.map((c: Record<string, unknown>) => ({
      recipe_id: String(c.recipe_id),
      grams: requireNumber(c.grams, `${p}.components.grams`, errors),
    })) : [],
    box_id: typeof r.box_id === 'string' ? r.box_id : null,
    pieces_per_box: requireNumber(r.pieces_per_box, `${p}.pieces_per_box`, errors),
    show_each_including_box: r.show_each_including_box === true,
  };
}

function validateAssembledProduct(raw: unknown, idx: number, errors: ImportError[]): AssembledProduct | null {
  const r = (raw ?? {}) as Record<string, unknown>;
  const p = `assembled_products[${idx}]`;
  const id = r.id;
  if (!validateId(id, `${p}.id`, errors)) return null;
  const components = Array.isArray(r.components) ? r.components.map((c: Record<string, unknown>, ci: number) => {
    if (c.type === 'cake_recipe_grams') return { type: 'cake_recipe_grams' as const, recipe_id: String(c.recipe_id), grams: requireNumber(c.grams, `${p}.components[${ci}].grams`, errors) };
    if (c.type === 'recipe_per_gram') return { type: 'recipe_per_gram' as const, recipe_id: String(c.recipe_id), grams: requireNumber(c.grams, `${p}.components[${ci}].grams`, errors) };
    if (c.type === 'ingredient_grams') return { type: 'ingredient_grams' as const, ingredient_id: String(c.ingredient_id), grams: requireNumber(c.grams, `${p}.components[${ci}].grams`, errors) };
    errors.push({ path: `${p}.components[${ci}].type`, message: 'Invalid component type' });
    return { type: 'cake_recipe_grams' as const, recipe_id: '', grams: 0 };
  }) : [];
  return {
    id: id as string,
    name: requireString(r.name ?? (id as string), `${p}.name`, errors),
    components,
    labour_hours_per_batch: requireNumber(r.labour_hours_per_batch, `${p}.labour_hours_per_batch`, errors),
    pieces_per_batch: requireNumber(r.pieces_per_batch, `${p}.pieces_per_batch`, errors),
    box_id: typeof r.box_id === 'string' ? r.box_id : null,
    pieces_per_box: requireNumber(r.pieces_per_box, `${p}.pieces_per_box`, errors),
  };
}

function validateSavedQuote(raw: unknown, idx: number, errors: ImportError[]): SavedQuote | null {
  const r = (raw ?? {}) as Record<string, unknown>;
  const p = `saved_quotes[${idx}]`;
  const id = r.id;
  if (!validateId(id, `${p}.id`, errors)) return null;

  const rawInput = (r.input ?? {}) as Record<string, unknown>;
  const tiers = Array.isArray(rawInput.tiers)
    ? rawInput.tiers.map((t: any) => {
        const tier: Record<string, unknown> = {
          size_kg: typeof t?.size_kg === 'number' && isFinite(t.size_kg) ? Math.max(0, t.size_kg) : 0,
        };
        if (t?.flavour_id !== undefined) tier.flavour_id = t.flavour_id;
        if (t?.filling_id !== undefined) tier.filling_id = t.filling_id;
        return tier as any;
      })
    : [];

  const rawDeco = (rawInput.decoration ?? {}) as Record<string, unknown>;
  const decoration: any = {
    fondant_kg: typeof rawDeco.fondant_kg === 'number' && isFinite(rawDeco.fondant_kg) ? Math.max(0, rawDeco.fondant_kg) : 0,
    prints: typeof rawDeco.prints === 'number' && isFinite(rawDeco.prints) ? Math.max(0, rawDeco.prints) : 0,
    flowers: typeof rawDeco.flowers === 'number' && isFinite(rawDeco.flowers) ? Math.max(0, rawDeco.flowers) : 0,
    toppers: typeof rawDeco.toppers === 'number' && isFinite(rawDeco.toppers) ? Math.max(0, rawDeco.toppers) : 0,
    time_hours: typeof rawDeco.time_hours === 'number' && isFinite(rawDeco.time_hours) ? Math.max(0, rawDeco.time_hours) : 0,
    others: typeof rawDeco.others === 'number' && isFinite(rawDeco.others) ? Math.max(0, rawDeco.others) : 0,
    delivery: typeof rawDeco.delivery === 'number' && isFinite(rawDeco.delivery) ? Math.max(0, rawDeco.delivery) : 0,
  };
  if (rawDeco.discount !== undefined) {
    decoration.discount = typeof rawDeco.discount === 'number' && isFinite(rawDeco.discount) ? Math.max(0, rawDeco.discount) : 0;
  }

  return {
    id: id as string,
    name: requireString(r.name ?? `Quote ${idx + 1}`, `${p}.name`, errors),
    created_at: typeof r.created_at === 'string' ? r.created_at : new Date().toISOString(),
    updated_at: typeof r.updated_at === 'string' ? r.updated_at : undefined,
    input: { tiers, decoration },
    result_snapshot: r.result_snapshot ?? null,
    notes: typeof r.notes === 'string' ? r.notes : undefined,
  };
}

function validateCustomer(raw: unknown, idx: number, errors: ImportError[]): Customer | null {
  const r = (raw ?? {}) as Record<string, unknown>;
  const p = `customers[${idx}]`;
  const id = r.id;
  if (!validateId(id, `${p}.id`, errors)) return null;
  return {
    id: id as string,
    name: requireString(r.name, `${p}.name`, errors),
    phone: typeof r.phone === 'string' ? r.phone : undefined,
    email: typeof r.email === 'string' ? r.email : undefined,
    address: typeof r.address === 'string' ? r.address : undefined,
    notes: typeof r.notes === 'string' ? r.notes : undefined,
  };
}

function validateOrder(raw: unknown, idx: number, errors: ImportError[]): Order | null {
  const r = (raw ?? {}) as Record<string, unknown>;
  const p = `orders[${idx}]`;
  const id = r.id;
  if (!validateId(id, `${p}.id`, errors)) return null;
  const status = r.status;
  if (!['Draft', 'Confirmed', 'Delivered', 'Cancelled'].includes(status as string)) {
    errors.push({ path: `${p}.status`, message: 'Invalid status' });
    return null;
  }
  return {
    id: id as string,
    customer_id: typeof r.customer_id === 'string' ? r.customer_id : null,
    quote_id: typeof r.quote_id === 'string' ? r.quote_id : null,
    order_date: typeof r.order_date === 'string' ? r.order_date : undefined,
    due_date: typeof r.due_date === 'string' ? r.due_date : undefined,
    status: status as OrderStatus,
    notes: typeof r.notes === 'string' ? r.notes : undefined,
  };
}

// ---------------------------------------------------------------------------
// Reference integrity check
// ---------------------------------------------------------------------------

function checkReferences(data: AppData, errors: ImportError[]): void {
  const ingIds = new Set(data.ingredients.map(i => i.id));
  const packIds = new Set(data.packaging_items.map(p => p.id));
  const recipeIds = new Set(data.recipes.map(r => r.id));
  const flavourIds = new Set(data.flavours.map(f => f.id));

  for (const recipe of data.recipes) {
    for (const [li, line] of recipe.lines.entries()) {
      if (line.ingredient_id && !ingIds.has(line.ingredient_id)) {
        errors.push({ path: `recipe[${recipe.id}].lines[${li}].ingredient_id`, message: `Ingredient "${line.ingredient_id}" not found` });
      }
    }
  }
  for (const flavour of data.flavours) {
    if (flavour.cost_model.type === 'recipe') {
      if (!recipeIds.has(flavour.cost_model.cake_recipe_id)) {
        errors.push({ path: `flavour[${flavour.id}].cost_model.cake_recipe_id`, message: `Recipe not found` });
      }
      if (!recipeIds.has(flavour.cost_model.frosting_recipe_id)) {
        errors.push({ path: `flavour[${flavour.id}].cost_model.frosting_recipe_id`, message: `Recipe not found` });
      }
    } else {
      for (const ref of flavour.cost_model.of) {
        if (!flavourIds.has(ref)) {
          errors.push({ path: `flavour[${flavour.id}].cost_model.of`, message: `Flavour "${ref}" not found` });
        }
      }
    }
  }
  for (const filling of data.fillings) {
    if (filling.source.type === 'recipe' && !recipeIds.has(filling.source.recipe_id)) {
      errors.push({ path: `filling[${filling.id}].source.recipe_id`, message: `Recipe not found` });
    }
    if (filling.source.type === 'ingredient' && !ingIds.has(filling.source.ingredient_id)) {
      errors.push({ path: `filling[${filling.id}].source.ingredient_id`, message: `Ingredient not found` });
    }
  }
  for (const bp of data.batch_products) {
    if (!recipeIds.has(bp.recipe_id)) {
      errors.push({ path: `batch_product[${bp.id}].recipe_id`, message: `Recipe not found` });
    }
    if (bp.box_id && !packIds.has(bp.box_id)) {
      errors.push({ path: `batch_product[${bp.id}].box_id`, message: `Packaging not found` });
    }
  }
  for (const ap of data.assembled_products) {
    if (ap.box_id && !packIds.has(ap.box_id)) {
      errors.push({ path: `assembled_product[${ap.id}].box_id`, message: `Packaging not found` });
    }
    for (const comp of ap.components) {
      if ((comp.type === 'cake_recipe_grams' || comp.type === 'recipe_per_gram') && !recipeIds.has(comp.recipe_id)) {
        errors.push({ path: `assembled_product[${ap.id}].components`, message: `Recipe not found` });
      }
      if (comp.type === 'ingredient_grams' && !ingIds.has(comp.ingredient_id)) {
        errors.push({ path: `assembled_product[${ap.id}].components`, message: `Ingredient not found` });
      }
    }
  }
  const customerIds = new Set((data.customers ?? []).map(c => c.id));
  const quoteIds = new Set((data.saved_quotes ?? []).map(q => q.id));
  for (const o of (data.orders ?? [])) {
    if (o.customer_id && !customerIds.has(o.customer_id)) {
      errors.push({ path: `order[${o.id}].customer_id`, message: `Customer not found` });
    }
    if (o.quote_id && !quoteIds.has(o.quote_id)) {
      errors.push({ path: `order[${o.id}].quote_id`, message: `Quote not found` });
    }
  }
}

// ---------------------------------------------------------------------------
// Count helper
// ---------------------------------------------------------------------------

function countChanges<T extends { id: Id }>(existing?: T[], incoming?: T[]) {
  const safeExisting = existing ?? [];
  const safeIncoming = incoming ?? [];
  const existingMap = new Map(safeExisting.map(x => [x.id, x]));
  let add = 0, update = 0, unchanged = 0;
  for (const item of safeIncoming) {
    if (!existingMap.has(item.id)) add++;
    else if (JSON.stringify(existingMap.get(item.id)) !== JSON.stringify(item)) update++;
    else unchanged++;
  }
  return { add, update, unchanged };
}

// ---------------------------------------------------------------------------
// Parse and validate import
// ---------------------------------------------------------------------------

export function parseImportFile(content: string, currentData: AppData): ImportPreview {
  const errors: ImportError[] = [];
  const warnings: string[] = [];
  let raw: Record<string, unknown>;

  try {
    raw = JSON.parse(content);
  } catch {
    return {
      valid: false,
      errors: [{ path: 'file', message: 'Invalid JSON' }],
      warnings: [],
      counts: emptyPreviewCounts(),
      parsed: {},
    };
  }

  if (raw.format !== FORMAT_FIELD) {
    errors.push({ path: 'format', message: `Expected "${FORMAT_FIELD}", got "${raw.format}"` });
  }

  const sv = String(raw.schema_version ?? '');
  const majorVersion = parseInt(sv.split('.')[0] ?? '0');
  const currentMajor = parseInt(CURRENT_SCHEMA_VERSION.split('.')[0]);
  if (majorVersion > currentMajor) {
    return {
      valid: false,
      errors: [{ path: 'schema_version', message: `Schema version ${sv} is newer than supported (${CURRENT_SCHEMA_VERSION})` }],
      warnings: [],
      counts: emptyPreviewCounts(),
      parsed: {},
    };
  }

  const parsed: Partial<AppData> = {};

  if (raw.settings !== undefined) {
    parsed.settings = validateSettings(raw.settings, errors);
  }
  if (Array.isArray(raw.ingredients)) {
    parsed.ingredients = raw.ingredients.map((x, i) => validateIngredient(x, i, errors)).filter(Boolean) as Ingredient[];
  }
  if (Array.isArray(raw.packaging_items)) {
    parsed.packaging_items = raw.packaging_items.map((x, i) => validatePackaging(x, i, errors)).filter(Boolean) as PackagingItem[];
  }
  if (Array.isArray(raw.recipes)) {
    parsed.recipes = raw.recipes.map((x, i) => validateRecipe(x, i, errors)).filter(Boolean) as Recipe[];
  }
  if (Array.isArray(raw.flavours)) {
    parsed.flavours = raw.flavours.map((x, i) => validateFlavour(x, i, errors)).filter(Boolean) as Flavour[];
  }
  if (Array.isArray(raw.fillings)) {
    parsed.fillings = raw.fillings.map((x, i) => validateFilling(x, i, errors)).filter(Boolean) as Filling[];
  }
  if (Array.isArray(raw.batch_products)) {
    parsed.batch_products = raw.batch_products.map((x, i) => validateBatchProduct(x, i, errors)).filter(Boolean) as BatchProduct[];
  }
  if (Array.isArray(raw.assembled_products)) {
    parsed.assembled_products = raw.assembled_products.map((x, i) => validateAssembledProduct(x, i, errors)).filter(Boolean) as AssembledProduct[];
  }
  if (Array.isArray(raw.size_guide)) {
    parsed.size_guide = raw.size_guide as SizeGuideEntry[];
  }
  if (Array.isArray(raw.saved_quotes)) {
    parsed.saved_quotes = raw.saved_quotes.map((x, i) => validateSavedQuote(x, i, errors)).filter(Boolean) as SavedQuote[];
  }
  if (sv === '1.0') {
    parsed.customers = [];
    parsed.orders = [];
  } else {
    if (Array.isArray(raw.customers)) {
      parsed.customers = raw.customers.map((x, i) => validateCustomer(x, i, errors)).filter(Boolean) as Customer[];
    }
    if (Array.isArray(raw.orders)) {
      parsed.orders = raw.orders.map((x, i) => validateOrder(x, i, errors)).filter(Boolean) as Order[];
    }
  }

  // Reference integrity check on merged data
  if (errors.length === 0) {
    const merged: AppData = {
      ...currentData,
      ...parsed,
    };
    checkReferences(merged, errors);
  }

  const counts = {
    settings: !!parsed.settings,
    ingredients: countChanges(currentData.ingredients, parsed.ingredients ?? []),
    packaging_items: countChanges(currentData.packaging_items, parsed.packaging_items ?? []),
    recipes: countChanges(currentData.recipes, parsed.recipes ?? []),
    flavours: countChanges(currentData.flavours, parsed.flavours ?? []),
    fillings: countChanges(currentData.fillings, parsed.fillings ?? []),
    batch_products: countChanges(currentData.batch_products, parsed.batch_products ?? []),
    assembled_products: countChanges(currentData.assembled_products, parsed.assembled_products ?? []),
    saved_quotes: countChanges(currentData.saved_quotes, parsed.saved_quotes ?? []),
    customers: countChanges(currentData.customers, parsed.customers ?? []),
    orders: countChanges(currentData.orders, parsed.orders ?? []),
  };

  return { valid: errors.length === 0, errors, warnings, counts, parsed };
}

function emptyPreviewCounts() {
  return {
    settings: false,
    ingredients: { add: 0, update: 0, unchanged: 0 },
    packaging_items: { add: 0, update: 0, unchanged: 0 },
    recipes: { add: 0, update: 0, unchanged: 0 },
    flavours: { add: 0, update: 0, unchanged: 0 },
    fillings: { add: 0, update: 0, unchanged: 0 },
    batch_products: { add: 0, update: 0, unchanged: 0 },
    assembled_products: { add: 0, update: 0, unchanged: 0 },
    saved_quotes: { add: 0, update: 0, unchanged: 0 },
    customers: { add: 0, update: 0, unchanged: 0 },
