                        </div>
                      )}
                    </div>
                  </div>
                </div>
              )}

              {editingFlavour.cost_model.type === 'average' && (
                <div className="form-group">
                  <label>Average of flavours (recipe-type only)</label>
                  <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
                    {[...data.flavours].filter(f => f.cost_model.type === 'recipe' && f.id !== editingFlavour.id).sort((a, b) => a.name.localeCompare(b.name)).map(f => {
                      const cm = editingFlavour.cost_model as { type: 'average'; of: string[] };
                      const checked = cm.of.includes(f.id);
                      return (
                        <label key={f.id} style={{ display: 'flex', alignItems: 'center', gap: 8, cursor: 'pointer', fontSize: 13 }}>
                          <input
                            type="checkbox"
                            checked={checked}
                            onChange={() => setEditingFlavour(ef => {
                              if (!ef) return ef;
                              const cm = ef.cost_model as { type: 'average'; of: string[] };
                              const of = checked ? cm.of.filter(x => x !== f.id) : [...cm.of, f.id];
                              return { ...ef, cost_model: { type: 'average', of } };
                            })}
                          />
                          {f.name}
                        </label>
                      );
                    })}
                  </div>
                </div>
              )}

              <div className="form-group">
                <label>Add-on cost per kg ({cur}) — plain ingredient cost</label>
                <NumberInput value={editingFlavour.addon_cost_per_kg} onChange={v => setEditingFlavour(f => f && ({ ...f, addon_cost_per_kg: v }))} step={1} />
                <span className="input-hint">Overhead ({(data.settings.overhead_pct * 100).toFixed(0)}%) is added automatically to this amount</span>
              </div>

              {/* Live preview */}
              {(() => {
                const previewData = { ...data, flavours: [...data.flavours.filter(f => f.id !== editingFlavour.id), editingFlavour] };
                const res = compute(previewData, null, batchMultipliers).flavours[editingFlavour.id];
                if (!res) return null;
                return (
                  <div className="success-banner">
                    Price per kg: {cur} {res.price_per_kg.toFixed(4)}
                    (base {cur} {res.base.toFixed(4)} + addon {cur} {(editingFlavour.addon_cost_per_kg * (1 + data.settings.overhead_pct)).toFixed(4)})
                  </div>
                );
              })()}
            </div>
            <div className="modal-footer">
              <button className="btn btn-ghost" onClick={() => setEditingFlavour(null)}>Cancel</button>
              <button className="btn btn-primary" onClick={saveFlavour} disabled={!editingFlavour.name.trim()}>Save</button>
            </div>
          </div>
        </div>
      )}

      {/* Filling editor */}
      {editingFilling && (
        <div className="modal-backdrop" onClick={() => setEditingFilling(null)}>
          <div className="modal" onClick={e => e.stopPropagation()}>
            <div className="modal-header">
              <h2 className="modal-title">{isNew ? 'Add filling' : `Edit: ${editingFilling.name}`}</h2>
              <button className="btn btn-ghost btn-sm" onClick={() => setEditingFilling(null)}>✕</button>
            </div>
            <div className="modal-body">
              <div className="form-group">
                <label>Name *</label>
                <input className="input" value={editingFilling.name} onChange={e => setEditingFilling(f => f && ({ ...f, name: e.target.value }))} />
              </div>
              <div className="form-group">
                <label>Source type</label>
                <select
                  className="select"
                  value={editingFilling.source.type}
                  onChange={e => setEditingFilling(f => f && ({
                    ...f,
                    source: e.target.value === 'recipe'
                      ? { type: 'recipe', recipe_id: frostingRecipes[0]?.id ?? '' }
                      : { type: 'ingredient', ingredient_id: data.ingredients.find(i => i.unit_type === 'g')?.id ?? '' },
                  }))}
                >
                  <option value="recipe">Recipe (frosting/filling kind)</option>
                  <option value="ingredient">Bought ingredient (jam, spreads …)</option>
                </select>
              </div>
              {editingFilling.source.type === 'recipe' && (
                <div className="form-group">
                  <label>Recipe</label>
                  <div style={{ display: 'flex', gap: 6, alignItems: 'center' }}>
                    <select className="select" value={editingFilling.source.recipe_id} onChange={e => setEditingFilling(f => f && ({ ...f, source: { type: 'recipe', recipe_id: e.target.value } }))} style={{ flex: 1 }}>
                      {frostingRecipes.map(r => <option key={r.id} value={r.id}>{r.name}</option>)}
                    </select>
                    {editingFilling.source.recipe_id && (
                      <div style={{ width: 80 }}>
                        <NumberInput value={batchMultipliers[(editingFilling.source as any).recipe_id] ?? 1} onChange={v => setBatchMultipliers(s => ({ ...s, [(editingFilling.source as any).recipe_id]: v }))} min={0} step={0.1} placeholder="Scale" />
                      </div>
                    )}
                  </div>
                </div>
              )}
              {editingFilling.source.type === 'ingredient' && (
                <div className="form-group">
                  <label>Ingredient (priced per gram)</label>
                  <select className="select" value={editingFilling.source.ingredient_id} onChange={e => setEditingFilling(f => f && ({ ...f, source: { type: 'ingredient', ingredient_id: e.target.value } }))}>
                    {[...data.ingredients.filter(i => i.unit_type === 'g')].sort((a, b) => a.name.localeCompare(b.name)).map(i => <option key={i.id} value={i.id}>{i.name}</option>)}
                  </select>
                </div>
              )}
              {/* Live preview */}
              {(() => {
                const previewData = { ...data, fillings: [...data.fillings.filter(f => f.id !== editingFilling.id), editingFilling] };
                const res = compute(previewData, null, batchMultipliers).fillings[editingFilling.id];
                if (!res) return null;
                return (
                  <div className="success-banner">
                    Cost per kg of cake: {cur} {res.cost_per_kg.toFixed(4)}
                    {' '}(at {data.settings.filling_grams_per_kg}g/kg)
                  </div>
                );
              })()}
            </div>
            <div className="modal-footer">
              <button className="btn btn-ghost" onClick={() => setEditingFilling(null)}>Cancel</button>
              <button className="btn btn-primary" onClick={saveFilling} disabled={!editingFilling.name.trim()}>Save</button>
            </div>
          </div>
        </div>
      )}

      {explainFlavour && result.flavours[explainFlavour] && (
        <ExplainPanel
          title={data.flavours.find(f => f.id === explainFlavour)?.name ?? explainFlavour}
          audit={result.flavours[explainFlavour].audit}
          currency={cur}
          onClose={() => setExplainFlavour(null)}
        />
      )}

      {explainFilling && result.fillings[explainFilling] && (
        <ExplainPanel
          title={data.fillings.find(f => f.id === explainFilling)?.name ?? explainFilling}
          audit={result.fillings[explainFilling].audit}
          currency={cur}
          onClose={() => setExplainFilling(null)}
        />
      )}

      {deleteTarget && (
        <ConfirmDialog
          message={`Delete "${deleteTarget.name}"?`}
          onConfirm={doDelete}
          onCancel={() => setDeleteTarget(null)}
          confirmLabel="Delete"
          danger
        />
      )}
    </div>
  );
}

import { useState, useRef } from 'react';
import { useStore } from '../../store/store';
import {
  exportAllData,
  downloadJSON,
  downloadBlankTemplate,
  getExportFilename,
  parseImportFile,
  exportIngredientsCSV,
  exportPackagingCSV,
  importIngredientsCSV,
  MAX_IMPORT_SIZE
} from '../../io/io';
import type { ImportPreview } from '../../io/io';
import type { AppData } from '../../engine/types';

type PartialKey = keyof AppData;

export function ImportExportPage() {
  const { state, dispatch } = useStore();
  const fileInputRef = useRef<HTMLInputElement>(null);
  const csvInputRef = useRef<HTMLInputElement>(null);

  // Partial Export selection
  const [selectedExportGroups, setSelectedExportGroups] = useState<Record<string, boolean>>({
    settings: true,
    ingredients: true,
    packaging_items: true,
    recipes: true,
    flavours: true,
    fillings: true,
    batch_products: true,
    assembled_products: true,
    size_guide: true,
    saved_quotes: true,
  });

  // Import State
  const [preview, setPreview] = useState<ImportPreview | null>(null);
  const [importMode, setImportMode] = useState<'replace' | 'merge' | 'replace_selected'>('replace');
  const [selectedImportGroups, setSelectedImportGroups] = useState<PartialKey[]>([
    'ingredients', 'packaging_items', 'recipes', 'flavours', 'fillings', 'batch_products', 'assembled_products', 'saved_quotes'
  ]);
  const [importStatus, setImportStatus] = useState<{ type: 'success' | 'error'; message: string } | null>(null);

  // CSV State
  const [csvPricesOnly, setCsvPricesOnly] = useState(false);
  const [csvStatus, setCsvStatus] = useState<string | null>(null);

  // Drag and drop state
  const [isDragging, setIsDragging] = useState(false);

  // Handlers for Export
  const handleFullExport = () => {
    const jsonStr = exportAllData(state.data);
    const filename = getExportFilename();
    downloadJSON(jsonStr, filename);
  };

  const handlePartialExport = () => {
    const partial: Partial<AppData> = {};
    for (const [key, enabled] of Object.entries(selectedExportGroups)) {
      if (enabled) {
        (partial as any)[key] = (state.data as any)[key];
      }
    }
    const envelope = {
      format: 'bakery-costing-data',
      schema_version: '1.0',
      exported_at: new Date().toISOString(),
      app_version: '1.0.0',
      ...partial,
    };
    const jsonStr = JSON.stringify(envelope, null, 2);
    downloadJSON(jsonStr, `bakery-costing-partial-${new Date().toISOString().slice(0, 10)}.json`);
  };

  // Handler for File Selection
  const handleFile = (file: File) => {
    setImportStatus(null);
    if (!file.name.endsWith('.json')) {
      setImportStatus({ type: 'error', message: 'Only JSON files (.json) are supported.' });
      return;
    }
    if (file.size > MAX_IMPORT_SIZE) {
      setImportStatus({ type: 'error', message: 'File exceeds maximum allowed size of 20 MB.' });
      return;
    }

    const reader = new FileReader();
    reader.onload = e => {
      try {
        const text = e.target?.result as string;
        const res = parseImportFile(text, state.data);
        setPreview(res);
      } catch (err: any) {
        setImportStatus({ type: 'error', message: `Failed to read file: ${err.message}` });
      }
    };
    reader.readAsText(file);
  };

  const handleFileInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      handleFile(e.target.files[0]);
    }
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      handleFile(e.dataTransfer.files[0]);
    }
  };

  // Apply Import
  const handleApplyImport = () => {
    if (!preview || !preview.valid) return;
    try {
      let dataToImport = preview.parsed;
      if (importMode === 'replace_selected') {
        const filtered: Partial<AppData> = {};
        for (const grp of selectedImportGroups) {
          if ((preview.parsed as any)[grp] !== undefined) {
            (filtered as any)[grp] = (preview.parsed as any)[grp];
          }
        }
        dataToImport = filtered;
      }
      dispatch({
        type: 'IMPORT_DATA',
        data: dataToImport,
        mode: importMode,
      });
      setImportStatus({
        type: 'success',
        message: `Successfully imported dataset using mode "${importMode}".`,
      });
      setPreview(null);
      if (fileInputRef.current) fileInputRef.current.value = '';
    } catch (err: any) {
      setImportStatus({ type: 'error', message: `Import error: ${err.message}` });
    }
  };

  // Undo Import
  const handleUndo = () => {
    if (!state.undoSnapshot) return;
    dispatch({ type: 'UNDO_IMPORT' });
    setImportStatus({ type: 'success', message: 'Undid last import and restored prior snapshot.' });
  };

  // CSV Import
  const handleCsvFile = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!e.target.files || !e.target.files[0]) return;
    const file = e.target.files[0];
    const reader = new FileReader();
    reader.onload = ev => {
      try {
        const content = ev.target?.result as string;
        const { items, errors } = importIngredientsCSV(content, state.data.ingredients, csvPricesOnly);
        if (errors.length > 0) {
          setCsvStatus(`Imported with warnings: ${errors.join(', ')}`);
        } else {
          setCsvStatus(`Successfully updated ingredients from CSV (${items.length} records total).`);
        }
        dispatch({
          type: 'IMPORT_DATA',
          data: { ingredients: items },
          mode: 'replace_selected',
        });
      } catch (err: any) {
        setCsvStatus(`CSV Import Error: ${err.message}`);
      }
    };
    reader.readAsText(file);
  };

  return (
    <div style={{ maxWidth: 960, margin: '0 auto', display: 'flex', flexDirection: 'column', gap: 24 }}>
      {/* Header */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <div>
          <h2>Import & Export</h2>
          <div style={{ color: 'var(--text-muted)', fontSize: 13, marginTop: 4 }}>
            Full system backups, selective data transfers, spreadsheet CSV sync, and template downloads.
          </div>
        </div>
        {state.undoSnapshot && (
          <button className="btn btn-warning" onClick={handleUndo}>
            ↶ Undo Last Import
          </button>
        )}
      </div>

      {importStatus && (
        <div className={importStatus.type === 'success' ? 'success-banner' : 'error-banner'}>
          {importStatus.type === 'success' ? '✓ ' : '⚠️ '}
          {importStatus.message}
        </div>
      )}

      {/* Import Section */}
      <div className="card">
        <h3 style={{ fontSize: 16, marginBottom: 14 }}>Import JSON Dataset</h3>
        <p style={{ fontSize: 13, color: 'var(--text-secondary)', marginBottom: 16 }}>
          Select or drop a standard bakery costing JSON export. Data will be inspected and validated before any changes are applied.
        </p>

        <div
          onDragOver={e => { e.preventDefault(); setIsDragging(true); }}
          onDragLeave={() => setIsDragging(false)}
          onDrop={handleDrop}
          style={{
            border: `2px dashed ${isDragging ? 'var(--accent)' : 'var(--border)'}`,
            borderRadius: 8,
            padding: '36px 20px',
            textAlign: 'center',
            background: isDragging ? 'rgba(167, 139, 250, 0.08)' : 'var(--bg-surface)',
            cursor: 'pointer',
            transition: 'border-color 150ms, background-color 150ms',
          }}
          onClick={() => fileInputRef.current?.click()}
        >
          <div style={{ fontSize: 36, marginBottom: 10 }}>📥</div>
          <div style={{ fontSize: 15, fontWeight: 600, color: 'var(--text-primary)', marginBottom: 4 }}>
            Click or drag & drop a .json file here
          </div>
          <div style={{ fontSize: 12, color: 'var(--text-muted)' }}>
            Strict validation against schema 1.0 (max 20 MB)
          </div>
          <input
            type="file"
            ref={fileInputRef}
            onChange={handleFileInputChange}
            accept=".json"
            style={{ display: 'none' }}
          />
        </div>

        {/* Import Preview Modal / Card */}
        {preview && (
          <div style={{ marginTop: 20, padding: 16, background: 'var(--bg-surface)', borderRadius: 8, border: '1px solid var(--border)' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 12 }}>
              <h4 style={{ fontSize: 15 }}>Import Preview</h4>
              <span className={`badge ${preview.valid ? 'badge-success' : 'badge-danger'}`}>
                {preview.valid ? '✓ Valid Dataset' : '⚠️ Has Validation Errors'}
              </span>
            </div>

            {/* Validation Errors */}
            {preview.errors.length > 0 && (
              <div className="error-banner" style={{ marginBottom: 12 }}>
                <strong>Blocking Validation Errors:</strong>
                <ul style={{ margin: '6px 0 0 16px', fontSize: 12 }}>
                  {preview.errors.map((e, idx) => (
                    <li key={idx}><strong>{e.path}:</strong> {e.message}</li>
                  ))}
                </ul>
              </div>
            )}

            {/* Warnings */}
            {preview.warnings.length > 0 && (
              <div className="warning-banner" style={{ marginBottom: 12 }}>
                <strong>Warnings:</strong>
                <ul style={{ margin: '6px 0 0 16px', fontSize: 12 }}>
                  {preview.warnings.map((w, idx) => (
                    <li key={idx}>{w}</li>
                  ))}
                </ul>
              </div>
            )}

            {/* Counts Table */}
            <div className="table-wrapper" style={{ marginBottom: 16 }}>
              <table className="table">
                <thead>
                  <tr>
                    <th>Entity Group</th>
                    <th>To Add</th>
                    <th>To Update</th>
                    <th>Unchanged</th>
                  </tr>
                </thead>
                <tbody>
                  {Object.entries(preview.counts).map(([group, val]) => {
                    if (typeof val === 'boolean') {
                      return (
                        <tr key={group}>
                          <td style={{ textTransform: 'capitalize' }}>{group.replace('_', ' ')}</td>
                          <td colSpan={3} style={{ color: val ? 'var(--accent)' : 'var(--text-muted)' }}>
                            {val ? 'New settings present in file' : 'No settings in file'}
                          </td>
                        </tr>
                      );
                    }
                    return (
                      <tr key={group}>
                        <td style={{ textTransform: 'capitalize' }}>{group.replace('_', ' ')}</td>
                        <td style={{ color: val.add > 0 ? 'var(--accent-green)' : 'inherit' }}>{val.add}</td>
                        <td style={{ color: val.update > 0 ? 'var(--accent-amber)' : 'inherit' }}>{val.update}</td>
                        <td style={{ color: 'var(--text-muted)' }}>{val.unchanged}</td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>

            {/* Mode selection */}
            <div style={{ marginBottom: 16 }}>
              <label style={{ display: 'block', fontSize: 13, fontWeight: 600, marginBottom: 8 }}>
                Select Import Application Mode:
              </label>
              <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
                <label style={{ display: 'flex', alignItems: 'center', gap: 8, fontSize: 13, cursor: 'pointer' }}>
                  <input
                    type="radio"
                    name="importMode"
                    value="replace"
                    checked={importMode === 'replace'}
                    onChange={() => setImportMode('replace')}
                  />
                  <span><strong>Replace Everything:</strong> Groups present in file replace current data completely; groups absent in file are retained.</span>
                </label>
                <label style={{ display: 'flex', alignItems: 'center', gap: 8, fontSize: 13, cursor: 'pointer' }}>
                  <input
                    type="radio"
                    name="importMode"
                    value="merge"
                    checked={importMode === 'merge'}
                    onChange={() => setImportMode('merge')}
                  />
                  <span><strong>Merge:</strong> Upsert records by ID; existing records not mentioned in the file are never deleted.</span>
                </label>
                <label style={{ display: 'flex', alignItems: 'center', gap: 8, fontSize: 13, cursor: 'pointer' }}>
                  <input
                    type="radio"
                    name="importMode"
                    value="replace_selected"
                    checked={importMode === 'replace_selected'}
                    onChange={() => setImportMode('replace_selected')}
                  />
                  <span><strong>Replace Selected Groups Only:</strong> Choose specific catalogs below to replace.</span>
                </label>
              </div>

              {importMode === 'replace_selected' && (
                <div style={{ marginTop: 12, padding: 12, background: 'var(--bg-base)', borderRadius: 6, display: 'flex', flexWrap: 'wrap', gap: 12 }}>
                  {[
                    'settings', 'ingredients', 'packaging_items', 'recipes', 'flavours', 'fillings', 'batch_products', 'assembled_products', 'saved_quotes'
                  ].map(grp => (
                    <label key={grp} style={{ display: 'flex', alignItems: 'center', gap: 6, fontSize: 12, cursor: 'pointer' }}>
                      <input
                        type="checkbox"
                        checked={selectedImportGroups.includes(grp as PartialKey)}
                        onChange={e => {
                          if (e.target.checked) setSelectedImportGroups(prev => [...prev, grp as PartialKey]);
                          else setSelectedImportGroups(prev => prev.filter(g => g !== grp));
                        }}
                      />
                      <span style={{ textTransform: 'capitalize' }}>{grp.replace('_', ' ')}</span>
                    </label>
                  ))}
                </div>
              )}
            </div>

            <div style={{ display: 'flex', justifyContent: 'flex-end', gap: 12 }}>
              <button className="btn btn-secondary" onClick={() => setPreview(null)}>Cancel</button>
              <button
                className="btn btn-primary"
                onClick={handleApplyImport}
                disabled={!preview.valid}
              >
                Apply Import (Atomic)
              </button>
            </div>
          </div>
        )}
      </div>

      {/* Export Section */}
      <div className="card">
        <h3 style={{ fontSize: 16, marginBottom: 14 }}>Export Data</h3>

        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(320px, 1fr))', gap: 20 }}>
          {/* Full Export */}
          <div style={{ padding: 16, background: 'var(--bg-surface)', borderRadius: 8, border: '1px solid var(--border)' }}>
            <h4 style={{ fontSize: 14, marginBottom: 8 }}>Complete Database Backup</h4>
            <p style={{ fontSize: 12, color: 'var(--text-muted)', marginBottom: 16 }}>
              Exports all settings, ingredients, packaging, recipes, flavours, products, size guide, and saved quotes into one standard JSON file.
            </p>
            <button className="btn btn-primary" style={{ width: '100%' }} onClick={handleFullExport}>
              Download Full Export (.json)
            </button>
          </div>

          {/* Partial Export */}
          <div style={{ padding: 16, background: 'var(--bg-surface)', borderRadius: 8, border: '1px solid var(--border)' }}>
            <h4 style={{ fontSize: 14, marginBottom: 8 }}>Partial / Selective Export</h4>
            <p style={{ fontSize: 12, color: 'var(--text-muted)', marginBottom: 12 }}>
              Tick the entity categories you want to include in the exported file:
            </p>
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 8, marginBottom: 16 }}>
              {Object.keys(selectedExportGroups).map(k => (
                <label key={k} style={{ display: 'flex', alignItems: 'center', gap: 6, fontSize: 12, cursor: 'pointer' }}>
                  <input
                    type="checkbox"
                    checked={selectedExportGroups[k]}
                    onChange={e => setSelectedExportGroups(prev => ({ ...prev, [k]: e.target.checked }))}
                  />
                  <span style={{ textTransform: 'capitalize' }}>{k.replace('_', ' ')}</span>
                </label>
              ))}
            </div>
            <button className="btn btn-secondary" style={{ width: '100%' }} onClick={handlePartialExport}>
              Export Selected Categories
            </button>
          </div>
        </div>
      </div>

      {/* CSV Spreadsheet Sync & Blank Template */}
      <div className="card">
        <h3 style={{ fontSize: 16, marginBottom: 14 }}>Spreadsheet Sync & Blank Templates</h3>

        {csvStatus && (
          <div className="success-banner" style={{ marginBottom: 16 }}>
            {csvStatus}
          </div>
        )}

        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(280px, 1fr))', gap: 20 }}>
          {/* CSV Export */}
          <div style={{ padding: 16, background: 'var(--bg-surface)', borderRadius: 8 }}>
            <h4 style={{ fontSize: 14, marginBottom: 8 }}>Export Spreadsheets (CSV)</h4>
            <p style={{ fontSize: 12, color: 'var(--text-muted)', marginBottom: 12 }}>
              Open directly in Microsoft Excel, Google Sheets, or Apple Numbers.
            </p>
            <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
              <button
                className="btn btn-secondary"
                onClick={() => {
                  const csv = exportIngredientsCSV(state.data.ingredients);
                  const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
                  const url = URL.createObjectURL(blob);
                  const a = document.createElement('a');
                  a.href = url;
                  a.download = `ingredients-${new Date().toISOString().slice(0, 10)}.csv`;
                  a.click();
                  URL.revokeObjectURL(url);
                }}
              >
                Export Ingredients (CSV)
              </button>
              <button
                className="btn btn-secondary"
                onClick={() => {
                  const csv = exportPackagingCSV(state.data.packaging_items);
                  const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
                  const url = URL.createObjectURL(blob);
                  const a = document.createElement('a');
                  a.href = url;
                  a.download = `packaging-${new Date().toISOString().slice(0, 10)}.csv`;
                  a.click();
                  URL.revokeObjectURL(url);
                }}
              >
                Export Packaging (CSV)
              </button>
            </div>
          </div>

          {/* CSV Import */}
          <div style={{ padding: 16, background: 'var(--bg-surface)', borderRadius: 8 }}>
            <h4 style={{ fontSize: 14, marginBottom: 8 }}>Import Ingredients from CSV</h4>
            <label style={{ display: 'flex', alignItems: 'center', gap: 8, fontSize: 12, marginBottom: 12, cursor: 'pointer' }}>
              <input
                type="checkbox"
                checked={csvPricesOnly}
                onChange={e => setCsvPricesOnly(e.target.checked)}
              />
              <span>Update prices only (leaves names &amp; units untouched)</span>
            </label>
            <input
              type="file"
              ref={csvInputRef}
              accept=".csv"
              onChange={handleCsvFile}
              style={{ display: 'none' }}
            />
            <button
              className="btn btn-secondary"
              style={{ width: '100%' }}
              onClick={() => csvInputRef.current?.click()}
            >
              Upload Ingredients CSV
            </button>
          </div>

          {/* Blank Template */}
          <div style={{ padding: 16, background: 'var(--bg-surface)', borderRadius: 8 }}>
            <h4 style={{ fontSize: 14, marginBottom: 8 }}>Blank Import Template</h4>
            <p style={{ fontSize: 12, color: 'var(--text-muted)', marginBottom: 12 }}>
              Download the official schema-valid empty template (Appendix B) to start populating your catalog from scratch.
            </p>
            <button className="btn btn-secondary" style={{ width: '100%' }} onClick={downloadBlankTemplate}>
              Download Blank Template (.json)
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

import { useState, useMemo } from 'react';
import { useStore } from '../../store/store';
import type { Ingredient, PriceHistoryEntry } from '../../engine/types';
import { NumberInput, SearchBar, ConfirmDialog } from '../components/Shared';
import { exportIngredientsCSV, importIngredientsCSV } from '../../io/io';

function generateId(existing: Ingredient[]): string {
  const ids = new Set(existing.map(i => i.id));
  for (let i = 1; i < 9999; i++) {
    const id = `ing_${i}`;
    if (!ids.has(id)) return id;
  }
  return 'ing_' + Date.now();
}

const EMPTY_ING: Omit<Ingredient, 'id'> = {
  name: '',
  unit_type: 'g',
  pack_quantity: 0,
  pack_price: 0,
  piece_weight_g: null,
  grams_per_tsp: null,
  notes: '',
};

function getUsedIn(id: string, data: ReturnType<typeof useStore>['state']['data']): string[] {
  const used: string[] = [];
  for (const r of data.recipes) {
    if (r.lines.some(l => l.ingredient_id === id)) used.push(`Recipe: ${r.name}`);
  }
  for (const f of data.fillings) {
    if (f.source.type === 'ingredient' && f.source.ingredient_id === id) used.push(`Filling: ${f.name}`);
  }
  for (const ap of data.assembled_products) {
    if (ap.components.some(c => c.type === 'ingredient_grams' && c.ingredient_id === id)) used.push(`Product: ${ap.name}`);
  }
  if (data.settings.fondant_ingredient_id === id) used.push('Settings: Fondant role');
  return used;
}

export function IngredientsPage() {
  const { state, dispatch } = useStore();
  const { data } = state;
  const cur = data.settings.currency_code;

  const [search, setSearch] = useState('');
  const [editing, setEditing] = useState<Ingredient | null>(null);
  const [isNew, setIsNew] = useState(false);
  const [deleteTarget, setDeleteTarget] = useState<Ingredient | null>(null);
  const [historyTarget, setHistoryTarget] = useState<Ingredient | null>(null);
  const [csvMode, setCsvMode] = useState(false);
  const [csvError, setCsvError] = useState('');

  const filtered = useMemo(() =>
    data.ingredients
      .filter(i =>
        i.name.toLowerCase().includes(search.toLowerCase()) ||
        i.id.toLowerCase().includes(search.toLowerCase())
      )
      .sort((a, b) => a.name.localeCompare(b.name)),
    [data.ingredients, search]);

  const openNew = () => {
    setIsNew(true);
    setEditing({ id: generateId(data.ingredients), ...EMPTY_ING });
  };

  const openEdit = (ing: Ingredient) => {
    setIsNew(false);
    setEditing({ ...ing });
  };

  const duplicate = (ing: Ingredient) => {
    const newId = generateId(data.ingredients);
    setIsNew(true);
    setEditing({ ...ing, id: newId, name: ing.name + ' (copy)' });
  };

  const save = () => {
    if (!editing || !editing.name.trim()) return;
    const normalized = { ...editing, name: editing.name.trim() };
    if (isNew) dispatch({ type: 'ADD_INGREDIENT', item: normalized });
    else dispatch({ type: 'UPDATE_INGREDIENT', item: normalized });
    setEditing(null);
  };

  const confirmDelete = (ing: Ingredient) => {
    const used = getUsedIn(ing.id, data);
    if (used.length > 0) {
      alert(`Cannot delete "${ing.name}" — used in:\n${used.join('\n')}`);
      return;
    }
    setDeleteTarget(ing);
  };

  const doDelete = () => {
    if (!deleteTarget) return;
    dispatch({ type: 'DELETE_INGREDIENT', id: deleteTarget.id });
    setDeleteTarget(null);
  };

  const exportCSV = () => {
    const csv = exportIngredientsCSV(data.ingredients);
    const blob = new Blob([csv], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; a.download = 'ingredients.csv'; a.click();
    URL.revokeObjectURL(url);
  };

  const importCSV = (e: React.ChangeEvent<HTMLInputElement>, pricesOnly = false) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = ev => {
      const content = ev.target?.result as string;
      const { items, errors } = importIngredientsCSV(content, data.ingredients, pricesOnly);
      if (errors.length > 0) { setCsvError(errors.join('\n')); return; }
      // Replace all
      dispatch({ type: 'IMPORT_DATA', data: { ingredients: items }, mode: 'replace_selected' });
      setCsvMode(false);
    };
    reader.readAsText(file);
    e.target.value = '';
  };

  return (
    <div>
      <div className="page-header">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="page-title">🧂 Ingredients</h1>
            <p className="page-subtitle">{data.ingredients.length} items · Prices per gram or per piece</p>
          </div>
          <div className="flex gap-8">
            <button className="btn btn-ghost btn-sm" onClick={() => setCsvMode(m => !m)}>CSV ▾</button>
            <button className="btn btn-primary btn-sm" onClick={openNew}>+ Add ingredient</button>
          </div>
        </div>
        {csvMode && (
          <div className="card mt-12" style={{ marginTop: 12 }}>
            <div className="flex gap-8 flex-wrap">
              <button className="btn btn-secondary btn-sm" onClick={exportCSV}>⬇ Export CSV</button>
              <label className="btn btn-secondary btn-sm" style={{ cursor: 'pointer' }}>
                ⬆ Import CSV <input type="file" accept=".csv" style={{ display: 'none' }} onChange={e => importCSV(e, false)} />
              </label>
              <label className="btn btn-secondary btn-sm" style={{ cursor: 'pointer' }}>
                💰 Update prices only <input type="file" accept=".csv" style={{ display: 'none' }} onChange={e => importCSV(e, true)} />
              </label>
            </div>
            {csvError && <div className="error-banner mt-8">{csvError}</div>}
          </div>
        )}
      </div>

      <div className="page-body">
        <div className="flex justify-between items-center mb-12">
          <SearchBar value={search} onChange={setSearch} placeholder="Search ingredients…" />
        </div>

        {filtered.length === 0 ? (
          <div className="empty-state">
            <div className="empty-state-icon">🧂</div>
            <div className="empty-state-title">No ingredients yet</div>
            <div className="empty-state-text">Add your first ingredient to get started</div>
            <button className="btn btn-primary" onClick={openNew}>+ Add ingredient</button>
          </div>
        ) : (
          <div className="table-wrapper">
            <table>
              <thead>
                <tr>
                  <th>Name</th>
                  <th>Type</th>
                  <th>Pack qty</th>
                  <th>Pack price</th>
                  <th>Per kg / piece</th>
                  <th>Piece weight</th>
                  <th>g/tsp</th>
                  <th>Used in</th>
                  <th>Status</th>
                  <th></th>
                </tr>
              </thead>
              <tbody>
                {filtered.map(ing => {
                  const ppu = ing.pack_quantity > 0 ? ing.pack_price / ing.pack_quantity : 0;
                  const perKg = ing.unit_type === 'g' ? ppu * 1000 : ppu;
                  const priced = ing.pack_quantity > 0 && ing.pack_price > 0;
                  const usedIn = getUsedIn(ing.id, data).length;
                  return (
                    <tr key={ing.id}>
                      <td>
                        <div style={{ fontWeight: 600 }}>{ing.name}</div>
                        <div className="text-muted" style={{ fontSize: 11 }}>{ing.id}</div>
                      </td>
                      <td><span className="badge badge-muted">{ing.unit_type}</span></td>
                      <td className="td-mono">{ing.pack_quantity}</td>
                      <td className="td-mono">{cur} {ing.pack_price.toFixed(2)}</td>
                      <td className="td-mono text-green">{cur} {perKg.toFixed(2)}</td>
                      <td className="td-mono">{ing.piece_weight_g ? `${ing.piece_weight_g}g` : '—'}</td>
                      <td className="td-mono">{ing.grams_per_tsp ?? '—'}</td>
                      <td className="text-secondary text-sm">{usedIn || '—'}</td>
                      <td>
                        {!priced
                          ? <span className="badge badge-amber">Unpriced</span>
                          : <span className="badge badge-green">Priced</span>}
                      </td>
                      <td>
                        <div className="td-actions">
                          <button className="btn btn-ghost btn-sm btn-icon" onClick={() => setHistoryTarget(ing)} title="Price history">🕐</button>
                          <button className="btn btn-ghost btn-sm btn-icon" onClick={() => openEdit(ing)} title="Edit">✏️</button>
                          <button className="btn btn-ghost btn-sm btn-icon" onClick={() => duplicate(ing)} title="Duplicate">📋</button>
                          <button className="btn btn-danger btn-sm btn-icon" onClick={() => confirmDelete(ing)} title="Delete">🗑</button>
                        </div>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* Edit modal */}
      {editing && (
        <div className="modal-backdrop" onClick={() => setEditing(null)}>
          <div className="modal" onClick={e => e.stopPropagation()}>
            <div className="modal-header">
              <h2 className="modal-title">{isNew ? 'Add ingredient' : `Edit: ${editing.name}`}</h2>
              <button className="btn btn-ghost btn-sm" onClick={() => setEditing(null)}>✕</button>
            </div>
            <div className="modal-body">
              <div className="form-group">
                <label>Name *</label>
                <input className="input" value={editing.name} onChange={e => setEditing(v => v && ({ ...v, name: e.target.value }))} placeholder="e.g. All-purpose flour" />
              </div>
              <div className="form-row form-row-2">
                <div className="form-group">
                  <label>Unit type</label>
                  <select className="select" value={editing.unit_type} onChange={e => setEditing(v => v && ({ ...v, unit_type: e.target.value as 'g' | 'piece' }))}>
                    <option value="g">Grams (g) — bulk/liquid</option>
                    <option value="piece">Piece — eggs, lemons …</option>
                  </select>
                </div>
                <div className="form-group">
                  <label>Pack quantity ({editing.unit_type === 'g' ? 'grams in pack' : 'pieces in pack'})</label>
                  <NumberInput value={editing.pack_quantity} onChange={v => setEditing(p => p && ({ ...p, pack_quantity: v }))} />
                </div>
              </div>
              <div className="form-row form-row-2">
                <div className="form-group">
                  <label>Pack price ({cur})</label>
                  <NumberInput value={editing.pack_price} onChange={v => setEditing(p => p && ({ ...p, pack_price: v }))} step={0.01} />
                </div>
                {editing.unit_type === 'piece' && (
                  <div className="form-group">
                    <label>Piece weight (grams)</label>
                    <NumberInput value={editing.piece_weight_g ?? 0} onChange={v => setEditing(p => p && ({ ...p, piece_weight_g: v }))} />
                    <span className="input-hint">e.g. 50 for an egg</span>
                  </div>
                )}
                {editing.unit_type === 'g' && (
                  <div className="form-group">
                    <label>Grams per teaspoon</label>
                    <NumberInput value={editing.grams_per_tsp ?? 0} onChange={v => setEditing(p => p && ({ ...p, grams_per_tsp: v || null }))} />
                    <span className="input-hint">e.g. 6 for salt, 5 for baking powder</span>
                  </div>
                )}
              </div>
              <div className="form-group">
                <label>Notes (optional)</label>
                <input className="input" value={editing.notes ?? ''} onChange={e => setEditing(p => p && ({ ...p, notes: e.target.value }))} />
              </div>
              {editing.pack_quantity > 0 && editing.pack_price > 0 && (
                <div className="success-banner">
                  Price per {editing.unit_type === 'g' ? 'kg' : 'piece'}: {cur} {
                    editing.unit_type === 'g'
                      ? (editing.pack_price / editing.pack_quantity * 1000).toFixed(2)
                      : (editing.pack_price / editing.pack_quantity).toFixed(2)
                  }
                </div>
              )}
            </div>
            <div className="modal-footer">
              <button className="btn btn-ghost" onClick={() => setEditing(null)}>Cancel</button>
              <button className="btn btn-primary" onClick={save} disabled={!editing.name.trim()}>Save</button>
            </div>
          </div>
        </div>
      )}

      {deleteTarget && (
        <ConfirmDialog
          message={`Delete "${deleteTarget.name}"? This cannot be undone.`}
          onConfirm={doDelete}
          onCancel={() => setDeleteTarget(null)}
          confirmLabel="Delete"
          danger
        />
      )}

      {/* Price History Modal */}
      {historyTarget && (
        <div className="modal-backdrop" onClick={() => setHistoryTarget(null)}>
          <div className="modal modal-lg" onClick={e => e.stopPropagation()} style={{ maxWidth: 600 }}>
            <div className="modal-header">
              <h2 className="modal-title">🕐 Price History — {historyTarget.name}</h2>
              <button className="btn btn-ghost btn-sm" onClick={() => setHistoryTarget(null)}>✕</button>
            </div>
            <div className="modal-body">
              {(!historyTarget.price_history || historyTarget.price_history.length === 0) ? (
                <div style={{ textAlign: 'center', padding: '32px 0', color: 'var(--text-muted)', fontSize: 14 }}>
                  No price history yet. Editing and saving the pack price or quantity will automatically log an entry.
                </div>
              ) : (
                <>
                  <PriceSparkline history={historyTarget.price_history} unitType={historyTarget.unit_type} cur={cur} />
                  <div className="table-wrapper" style={{ marginTop: 16 }}>
                    <table>
                      <thead>
                        <tr>
                          <th>Date</th>
                          <th>Pack qty</th>
                          <th>Pack price</th>
                          <th>Per {historyTarget.unit_type === 'g' ? 'kg' : 'piece'}</th>
                          <th>Note</th>
                        </tr>
                      </thead>
                      <tbody>
                        {[...historyTarget.price_history].reverse().map((h, i) => {
                          const perUnit = h.pack_quantity > 0
                            ? (historyTarget.unit_type === 'g' ? h.pack_price / h.pack_quantity * 1000 : h.pack_price / h.pack_quantity)
                            : 0;
                          return (
                            <tr key={i}>
                              <td className="td-mono">{h.date}</td>
                              <td className="td-mono">{h.pack_quantity}</td>
                              <td className="td-mono">{cur} {h.pack_price.toFixed(2)}</td>
                              <td className="td-mono text-green">{cur} {perUnit.toFixed(2)}</td>
                              <td style={{ fontSize: 12, color: 'var(--text-secondary)' }}>{h.note || '—'}</td>
                            </tr>
                          );
                        })}
                      </tbody>
                    </table>
                  </div>
                </>
              )}
            </div>
            <div className="modal-footer">
              <div style={{ fontSize: 12, color: 'var(--text-muted)', flex: 1 }}>
                Current: {cur} {historyTarget.pack_price.toFixed(2)} / {historyTarget.pack_quantity} {historyTarget.unit_type === 'g' ? 'g' : 'pcs'}
              </div>
              <button className="btn btn-ghost" onClick={() => setHistoryTarget(null)}>Close</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

// ---------------------------------------------------------------------------
// Sparkline component (pure SVG, no external deps)
// ---------------------------------------------------------------------------
function PriceSparkline({ history, unitType, cur }: { history: PriceHistoryEntry[]; unitType: 'g' | 'piece'; cur: string }) {
  const values = history.map(h => h.pack_quantity > 0 ? (unitType === 'g' ? h.pack_price / h.pack_quantity * 1000 : h.pack_price / h.pack_quantity) : 0);
  if (values.length < 2) return null;
  const min = Math.min(...values);
  const max = Math.max(...values);
  const range = max - min || 1;
  const W = 540, H = 80, PAD = 8;
  const pts = values.map((v, i) => {
    const x = PAD + (i / (values.length - 1)) * (W - PAD * 2);
    const y = PAD + (1 - (v - min) / range) * (H - PAD * 2);
    return `${x.toFixed(1)},${y.toFixed(1)}`;
  }).join(' ');
  const last = values[values.length - 1];
  return (
    <div style={{ background: 'var(--bg-surface)', borderRadius: 'var(--r-md)', padding: '12px 16px', marginBottom: 8 }}>
      <div style={{ fontSize: 11, color: 'var(--text-muted)', marginBottom: 6 }}>Price per {unitType === 'g' ? 'kg' : 'piece'} over time</div>
      <svg viewBox={`0 0 ${W} ${H}`} width="100%" height={H} style={{ overflow: 'visible' }}>
        <polyline points={pts} fill="none" stroke="var(--accent)" strokeWidth="2" strokeLinejoin="round" strokeLinecap="round" />
        {values.map((v, i) => {
          const x = PAD + (i / (values.length - 1)) * (W - PAD * 2);
          const y = PAD + (1 - (v - min) / range) * (H - PAD * 2);
          return <circle key={i} cx={x} cy={y} r={3} fill="var(--accent)" />;
        })}
      </svg>
      <div style={{ textAlign: 'right', fontSize: 12, color: 'var(--accent)', fontWeight: 600 }}>
        Current: {cur} {last.toFixed(2)}
      </div>
    </div>
  );
}

import { useState, useMemo } from 'react';
import { useStore } from '../../store/store';
import type { Order, OrderStatus } from '../../engine/types';
import { generateId } from '../../engine/utils';

interface OrdersPageProps {
  onNavigate: (page: string) => void;
}

export function OrdersPage({ onNavigate }: OrdersPageProps) {
  const { state, dispatch } = useStore();
  const { orders, customers, saved_quotes } = state.data;

  const [filterStatus, setFilterStatus] = useState<string>('all');
  const [filterCustomer, setFilterCustomer] = useState<string>('all');

  const [editing, setEditing] = useState<Order | null>(null);
  const [isNew, setIsNew] = useState(false);
  const [deleteTarget, setDeleteTarget] = useState<Order | null>(null);

  const filtered = useMemo(() => {
    let res = orders;
    if (filterStatus !== 'all') {
      res = res.filter(o => o.status === filterStatus);
    }
    if (filterCustomer !== 'all') {
      res = res.filter(o => o.customer_id === filterCustomer);
    }
    return res.sort((a, b) => {
      const aDate = a.order_date || '';
      const bDate = b.order_date || '';
      return bDate.localeCompare(aDate); // descending by order date
    });
  }, [orders, filterStatus, filterCustomer]);

  const openNew = () => {
    setIsNew(true);
    setEditing({
      id: generateId('ord'),
      customer_id: null,
      quote_id: null,
      order_date: new Date().toISOString().split('T')[0],
      due_date: '',
      status: 'Draft',
      notes: ''
    });
  };

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editing) return;
    dispatch({ type: isNew ? 'ADD_ORDER' : 'UPDATE_ORDER', item: editing });
    setEditing(null);
  };

  const handleDelete = () => {
    if (!deleteTarget) return;
    dispatch({ type: 'DELETE_ORDER', id: deleteTarget.id });
    setDeleteTarget(null);
  };

  const handleOpenQuote = (quoteId: string) => {
    const q = saved_quotes.find(x => x.id === quoteId);
    if (q) {
      dispatch({ type: 'LOAD_SAVED_QUOTE', quote: q });
      onNavigate('quote');
    }
  };

  return (
    <div className="card" style={{ maxWidth: 1000, margin: '0 auto' }}>
      <div style={{ display: 'flex', flexWrap: 'wrap', justifyContent: 'space-between', alignItems: 'center', marginBottom: 20, gap: 12 }}>
        <div>
          <h2>Orders</h2>
          <div style={{ color: 'var(--text-muted)', fontSize: 13, marginTop: 4 }}>
            Track and manage your customer orders.
          </div>
        </div>
        <button className="btn btn-primary" onClick={openNew}>+ New Order</button>
      </div>

      <div className="form-row form-row-2" style={{ marginBottom: 20 }}>
        <div className="form-group" style={{ marginBottom: 0 }}>
          <label>Status Filter</label>
          <select className="select" style={{ width: '100%' }} value={filterStatus} onChange={e => setFilterStatus(e.target.value)}>
            <option value="all">All Statuses</option>
            <option value="Draft">Draft</option>
            <option value="Confirmed">Confirmed</option>
            <option value="Delivered">Delivered</option>
            <option value="Cancelled">Cancelled</option>
          </select>
        </div>
        <div className="form-group" style={{ marginBottom: 0 }}>
          <label>Customer Filter</label>
          <select className="select" style={{ width: '100%' }} value={filterCustomer} onChange={e => setFilterCustomer(e.target.value)}>
            <option value="all">All Customers</option>
            {customers.map(c => (
              <option key={c.id} value={c.id}>{c.name}</option>
            ))}
          </select>
        </div>
      </div>

      {filtered.length === 0 ? (
        <div className="empty-state">
          <div className="empty-state-icon">🛍️</div>
          <div className="empty-state-title">No orders found</div>
          <button className="btn btn-primary mt-12" onClick={openNew}>+ Create your first order</button>
        </div>
      ) : (
        <div className="table-wrapper">
          <table>
            <thead>
              <tr>
                <th>Customer</th>
                <th>Quote</th>
                <th>Dates</th>
                <th>Status</th>
                <th>Notes</th>
                <th style={{ width: 100 }}></th>
              </tr>
            </thead>
            <tbody>
              {filtered.map(o => {
                const customer = customers.find(c => c.id === o.customer_id);
                const quote = saved_quotes.find(q => q.id === o.quote_id);

                let badgeClass = 'badge-accent';
                if (o.status === 'Confirmed') badgeClass = 'badge-amber';
                if (o.status === 'Delivered') badgeClass = 'badge-success';
                if (o.status === 'Cancelled') badgeClass = 'badge-danger';

                return (
                  <tr key={o.id}>
                    <td>
                      <div style={{ fontWeight: 600 }}>{customer ? customer.name : <span className="text-muted">No Customer</span>}</div>
                    </td>
                    <td>
                      {quote ? (
                        <button className="btn btn-ghost btn-sm" onClick={() => handleOpenQuote(quote.id)} style={{ padding: '4px 8px' }}>
                          📄 {quote.name}
                        </button>
                      ) : (
                        <span className="text-muted" style={{ fontSize: 12 }}>No Quote</span>
                      )}
                    </td>
