                          min={0} step={0.1} placeholder="Scale"
                        />
                      </div>
                    )}
                  </div>
                </div>
              </div>
              <div className="form-row form-row-2">
                <div className="form-group">
                  <label>Pieces mode</label>
                  <select className="select" value={editingBatch.pieces_mode} onChange={e => setEditingBatch(p => p && ({ ...p, pieces_mode: e.target.value as 'by_weight' | 'fixed' }))}>
                    <option value="by_weight">By weight (recipe weight / piece weight)</option>
                    <option value="fixed">Fixed count</option>
                  </select>
                </div>
                {editingBatch.pieces_mode === 'by_weight' && (
                  <div className="form-group">
                    <label>Piece weight (g)</label>
                    <NumberInput value={editingBatch.piece_weight_g ?? 0} onChange={v => setEditingBatch(p => p && ({ ...p, piece_weight_g: v }))} />
                  </div>
                )}
                {editingBatch.pieces_mode === 'fixed' && (
                  <div className="form-group">
                    <label>Fixed pieces</label>
                    <NumberInput value={editingBatch.fixed_pieces ?? 0} onChange={v => setEditingBatch(p => p && ({ ...p, fixed_pieces: v }))} />
                  </div>
                )}
              </div>
              <div className="form-row form-row-3">
                <div className="form-group">
                  <label>Labour hours/batch</label>
                  <NumberInput value={editingBatch.labour_hours_per_batch} onChange={v => setEditingBatch(p => p && ({ ...p, labour_hours_per_batch: v }))} step={0.25} />
                </div>
                <div className="form-group">
                  <label>Box packaging</label>
                  <select className="select" value={editingBatch.box_id ?? ''} onChange={e => setEditingBatch(p => p && ({ ...p, box_id: e.target.value || null }))}>
                    <option value="">— none —</option>
                    {[...data.packaging_items].sort((a, b) => a.name.localeCompare(b.name)).map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
                  </select>
                </div>
                <div className="form-group">
                  <label>Pieces per box</label>
                  <NumberInput value={editingBatch.pieces_per_box} onChange={v => setEditingBatch(p => p && ({ ...p, pieces_per_box: v }))} />
                </div>
              </div>
              <div className="form-group">
                <Toggle
                  checked={editingBatch.show_each_including_box}
                  onChange={v => setEditingBatch(p => p && ({ ...p, show_each_including_box: v }))}
                  label="Show price per piece including box as headline (vs excluding box)"
                />
              </div>

              {/* Components */}
              <div>
                <div className="card-header" style={{ marginBottom: 8 }}>
                  <span className="card-title">Extra components per piece (e.g. macaron filling)</span>
                  <button className="btn btn-secondary btn-sm" onClick={() => setEditingBatch(p => p && ({ ...p, components: [...p.components, { recipe_id: frostingRecipes[0]?.id ?? '', grams: 15 }] }))}>
                    + Component
                  </button>
                </div>
                {editingBatch.components.map((comp, ci) => (
                  <div key={ci} style={{ display: 'grid', gridTemplateColumns: '1fr 100px auto', gap: 6, alignItems: 'center', marginBottom: 6 }}>
                    <div style={{ display: 'flex', gap: 6 }}>
                      <select className="select" value={comp.recipe_id} onChange={e => {
                        const comps = editingBatch.components.map((c, i) => i === ci ? { ...c, recipe_id: e.target.value } : c);
                        setEditingBatch(p => p && ({ ...p, components: comps }));
                      }} style={{ flex: 1 }}>
                        {[...data.recipes].sort((a, b) => a.name.localeCompare(b.name)).map(r => <option key={r.id} value={r.id}>{r.name}</option>)}
                      </select>
                      {comp.recipe_id && (
                        <div style={{ width: 80 }}>
                          <NumberInput
                            value={batchMultipliers[comp.recipe_id] ?? 1}
                            onChange={v => setBatchMultipliers(s => ({ ...s, [comp.recipe_id]: v }))}
                            min={0} step={0.1} placeholder="Scale"
                          />
                        </div>
                      )}
                    </div>
                    <NumberInput value={comp.grams} onChange={v => {
                      const comps = editingBatch.components.map((c, i) => i === ci ? { ...c, grams: v } : c);
                      setEditingBatch(p => p && ({ ...p, components: comps }));
                    }} placeholder="grams" />
                    <button className="btn btn-danger btn-sm btn-icon" onClick={() => setEditingBatch(p => p && ({ ...p, components: p.components.filter((_, i) => i !== ci) }))}>✕</button>
                  </div>
                ))}
              </div>

              {/* Live result */}
              {(() => {
                const prev = { ...data, batch_products: [...data.batch_products.filter(p => p.id !== editingBatch.id), editingBatch] };
                const res = compute(prev, null, batchMultipliers).batch_products[editingBatch.id];
                if (!res) return null;
                return (
                  <div className="success-banner" style={{ flexDirection: 'column', alignItems: 'flex-start', gap: 2 }}>
                    <b>Pieces: {res.pieces.toFixed(2)}</b>
                    <span>Unit cost: {fmt(res.unit_cost, cur)}</span>
                    <span>Each excl. box: {fmt(res.each_excluding_box, cur)}</span>
                    <span>Each incl. box: {fmt(res.each_including_box, cur)}</span>
                    <span>Box (full): {fmt(res.box_price, cur)}</span>
                    {res.warnings.length > 0 && <WarningsList warnings={res.warnings} limit={3} />}
                  </div>
                );
              })()}
            </div>
            <div className="modal-footer">
              <button className="btn btn-ghost" onClick={() => setEditingBatch(null)}>Cancel</button>
              <button className="btn btn-primary" onClick={saveBatch} disabled={!editingBatch.name.trim()}>Save</button>
            </div>
          </div>
        </div>
      )}

      {/* Assembled product editor */}
      {editingAssembled && (
        <div className="modal-backdrop" onClick={() => setEditingAssembled(null)}>
          <div className="modal modal-lg" onClick={e => e.stopPropagation()}>
            <div className="modal-header">
              <h2 className="modal-title">{isNew ? 'New assembled product' : `Edit: ${editingAssembled.name}`}</h2>
              <button className="btn btn-ghost btn-sm" onClick={() => setEditingAssembled(null)}>✕</button>
            </div>
            <div className="modal-body">
              <div className="form-group">
                <label>Name *</label>
                <input className="input" value={editingAssembled.name} onChange={e => setEditingAssembled(p => p && ({ ...p, name: e.target.value }))} />
              </div>
              <div className="form-row form-row-3">
                <div className="form-group">
                  <label>Labour hours/batch</label>
                  <NumberInput value={editingAssembled.labour_hours_per_batch} onChange={v => setEditingAssembled(p => p && ({ ...p, labour_hours_per_batch: v }))} step={0.25} />
                </div>
                <div className="form-group">
                  <label>Pieces per batch</label>
                  <NumberInput value={editingAssembled.pieces_per_batch} onChange={v => setEditingAssembled(p => p && ({ ...p, pieces_per_batch: v }))} />
                </div>
                <div className="form-group">
                  <label>Box</label>
                  <select className="select" value={editingAssembled.box_id ?? ''} onChange={e => setEditingAssembled(p => p && ({ ...p, box_id: e.target.value || null }))}>
                    <option value="">— none —</option>
                    {[...data.packaging_items].sort((a, b) => a.name.localeCompare(b.name)).map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
                  </select>
                </div>
              </div>
              <div className="form-group">
                <label>Pieces per box</label>
                <NumberInput value={editingAssembled.pieces_per_box} onChange={v => setEditingAssembled(p => p && ({ ...p, pieces_per_box: v }))} />
              </div>

              {/* Components */}
              <div>
                <div className="card-header" style={{ marginBottom: 8 }}>
                  <span className="card-title">Components</span>
                  <div className="flex gap-4">
                    <button className="btn btn-secondary btn-sm" onClick={() => addComponent('cake_recipe_grams')}>+ Cake grams</button>
                    <button className="btn btn-secondary btn-sm" onClick={() => addComponent('recipe_per_gram')}>+ Recipe/gram</button>
                    <button className="btn btn-secondary btn-sm" onClick={() => addComponent('ingredient_grams')}>+ Ingredient</button>
                  </div>
                </div>
                {editingAssembled.components.map((comp, ci) => (
                  <div key={ci} style={{ display: 'grid', gridTemplateColumns: '140px 1fr 80px auto', gap: 6, alignItems: 'center', marginBottom: 6 }}>
                    <span className="badge badge-muted" style={{ fontSize: 11 }}>
                      {comp.type === 'cake_recipe_grams' ? '🎂 Cake' : comp.type === 'recipe_per_gram' ? '🍮 Recipe' : '🧂 Ingredient'}
                    </span>
                    <div style={{ display: 'flex', gap: 6 }}>
                      <select className="select" value={comp.type === 'ingredient_grams' ? comp.ingredient_id : comp.recipe_id} onChange={e => {
                        if (comp.type === 'ingredient_grams') updateComponent(ci, { ingredient_id: e.target.value } as Partial<AssembledComponent>);
                        else updateComponent(ci, { recipe_id: e.target.value } as Partial<AssembledComponent>);
                      }} style={{ flex: 1 }}>
                        {comp.type === 'ingredient_grams'
                          ? [...data.ingredients].sort((a, b) => a.name.localeCompare(b.name)).map(i => <option key={i.id} value={i.id}>{i.name}</option>)
                          : (comp.type === 'cake_recipe_grams' ? cakeRecipes : frostingRecipes).map(r => <option key={r.id} value={r.id}>{r.name}</option>)
                        }
                      </select>
                      {comp.type !== 'ingredient_grams' && comp.recipe_id && (
                        <div style={{ width: 80 }}>
                          <NumberInput
                            value={batchMultipliers[comp.recipe_id] ?? 1}
                            onChange={v => setBatchMultipliers(s => ({ ...s, [comp.recipe_id]: v }))}
                            min={0} step={0.1} placeholder="Scale"
                          />
                        </div>
                      )}
                    </div>
                    <NumberInput value={comp.grams} onChange={v => updateComponent(ci, { grams: v } as Partial<AssembledComponent>)} placeholder="g" />
                    <button className="btn btn-danger btn-sm btn-icon" onClick={() => removeComponent(ci)}>✕</button>
                  </div>
                ))}
              </div>

              {/* Live result */}
              {(() => {
                const prev = { ...data, assembled_products: [...data.assembled_products.filter(p => p.id !== editingAssembled.id), editingAssembled] };
                const res = compute(prev, null, batchMultipliers).assembled_products[editingAssembled.id];
                if (!res) return null;
                return (
                  <div className="success-banner" style={{ flexDirection: 'column', alignItems: 'flex-start', gap: 2 }}>
                    <span>Unit cost: {fmt(res.unit_cost, cur)}</span>
                    <span>Labour/piece: {fmt(res.labour_piece, cur)}</span>
                    <span>Box/piece: {fmt(res.box_piece, cur)}</span>
                    <b>Price each: {fmt(res.price_each, cur)}</b>
                    {res.suggested_price_each !== undefined && (
                      <span style={{ fontSize: 12, color: 'var(--accent-amber)' }}>
                        Suggested: {fmt(res.suggested_price_each, cur)}
                      </span>
                    )}
                    {res.warnings.length > 0 && <WarningsList warnings={res.warnings} limit={3} />}
                  </div>
                );
              })()}
            </div>
            <div className="modal-footer">
              <button className="btn btn-ghost" onClick={() => setEditingAssembled(null)}>Cancel</button>
              <button className="btn btn-primary" onClick={saveAssembled} disabled={!editingAssembled.name.trim()}>Save</button>
            </div>
          </div>
        </div>
      )}

      {explainBatch && result.batch_products[explainBatch] && (
        <ExplainPanel
          title={data.batch_products.find(p => p.id === explainBatch)?.name ?? explainBatch}
          audit={result.batch_products[explainBatch].audit}
          currency={cur}
          onClose={() => setExplainBatch(null)}
        />
      )}

      {explainAssembled && result.assembled_products[explainAssembled] && (
        <ExplainPanel
          title={data.assembled_products.find(p => p.id === explainAssembled)?.name ?? explainAssembled}
          audit={result.assembled_products[explainAssembled].audit}
          currency={cur}
          onClose={() => setExplainAssembled(null)}
        />
      )}

      {deleteTarget && (
        <ConfirmDialog
          message={`Delete "${deleteTarget.name}"?`}
          onConfirm={doDelete}
          onCancel={() => setDeleteTarget(null)}
          confirmLabel="Delete"
          danger
        />
      )}
    </div>
  );
}

import { useState, useCallback, useMemo, useEffect } from 'react';
import { useStore } from '../../store/store';
import { compute } from '../../engine/engine';
import type { TierInput, SavedQuote } from '../../engine/types';
import { ExplainPanel } from '../components/ExplainPanel';
import { WarningsList } from '../components/WarningsList';
import { NumberInput } from '../components/Shared';

function fmt(n: number, cur: string): string {
  return `${cur} ${n.toFixed(2)}`;
}

export function QuotePage() {
  const { state, dispatch } = useStore();
  const { data, quoteInput, activeSavedQuote } = state;
  const { settings } = data;
  const cur = settings.currency_code;

  const [showExplain, setShowExplain] = useState(false);
  const [activeTiers, setActiveTiers] = useState(1); // how many tier cards shown

  // Save dialog state
  const [showSaveDialog, setShowSaveDialog] = useState(false);
  const [saveName, setSaveName] = useState('');
  const [saveNotes, setSaveNotes] = useState('');

  // Live calculation from current catalog
  const result = useMemo(() => compute(data, quoteInput), [data, quoteInput]);
  const liveQ = result.quote;

  // Displayed quote: if viewing a saved quote snapshot without recalculation, show snapshot
  const displayQ = useMemo(() => {
    if (activeSavedQuote && !activeSavedQuote.isRecalculated && activeSavedQuote.snapshot) {
      return activeSavedQuote.snapshot as typeof liveQ;
    }
    return liveQ;
  }, [activeSavedQuote, liveQ]);

  // Phase 5 — detect ingredient price changes since the quote was saved
  const priceChangedIngredients = useMemo(() => {
    if (!activeSavedQuote || !activeSavedQuote.snapshot) return [];
    const snapshot = activeSavedQuote.snapshot as any;
    if (!Array.isArray(snapshot?.ingredient_prices)) return [];
    return (snapshot.ingredient_prices as Array<{ id: string; pack_price: number; pack_quantity: number }>)
      .filter(sp => {
        const cur = data.ingredients.find(i => i.id === sp.id);
        return cur && (cur.pack_price !== sp.pack_price || cur.pack_quantity !== sp.pack_quantity);
      })
      .map(sp => data.ingredients.find(i => i.id === sp.id)!.name);
  }, [activeSavedQuote, data.ingredients]);

  // Expand active tiers if loaded quote has higher tiers filled
  useEffect(() => {
    let maxFilled = 1;
    quoteInput.tiers.forEach((t, i) => {
      if ((t.size_kg ?? 0) > 0) maxFilled = i + 1;
    });
    setActiveTiers(prev => Math.max(prev, maxFilled));
  }, [quoteInput.tiers]);

  const onInputModified = useCallback(() => {
    if (activeSavedQuote && !activeSavedQuote.isRecalculated) {
      dispatch({ type: 'RECALCULATE_SAVED_QUOTE' });
    }
  }, [activeSavedQuote, dispatch]);

  const updateDecoration = useCallback((field: keyof typeof quoteInput.decoration, value: number) => {
    onInputModified();
    dispatch({
      type: 'SET_QUOTE_INPUT',
      input: {
        ...quoteInput,
        decoration: { ...quoteInput.decoration, [field]: value },
      },
    });
  }, [dispatch, quoteInput, onInputModified]);

  const updateTier = useCallback((idx: number, update: Partial<TierInput>) => {
    onInputModified();
    const newTiers = quoteInput.tiers.map((t, i) => i === idx ? { ...t, ...update } : t);
    dispatch({ type: 'SET_QUOTE_INPUT', input: { ...quoteInput, tiers: newTiers } });
  }, [dispatch, quoteInput, onInputModified]);

  const flavourOptions = [...data.flavours].sort((a, b) => a.name.localeCompare(b.name));
  const fillingOptions = [...data.fillings].sort((a, b) => a.name.localeCompare(b.name));

  const copyText = () => {
    if (!displayQ) return;
    const lines = [
      `Bakery Quote`,
      `Tier Cost:   ${fmt(displayQ.tier_cost, cur)}`,
      `Overhead:    ${fmt(displayQ.overhead, cur)}`,
      `Packaging:   ${fmt(displayQ.packaging, cur)}`,
      `Delivery:    ${fmt(displayQ.delivery, cur)}`,
      `──────────────────`,
      `TOTAL COST:  ${fmt(displayQ.total_cost, cur)}`,
      `Profit:      ${fmt(displayQ.profit, cur)}`,
      ...(displayQ.discount > 0 ? [`Discount:    -${fmt(displayQ.discount, cur)}`] : []),
      `TOTAL PRICE: ${fmt(displayQ.total_price, cur)}`,
      `Margin:      ${(displayQ.margin_check * 100).toFixed(1)}%`,
    ];
    navigator.clipboard.writeText(lines.join('\n'));
  };

  const handleOpenSaveDialog = () => {
    const todayStr = new Date().toISOString().slice(0, 10);
    const defaultName = activeSavedQuote?.name || `Quote ${todayStr}`;
    setSaveName(defaultName);
    setSaveNotes(activeSavedQuote?.notes || '');
    setShowSaveDialog(true);
  };

  const handleSaveQuote = () => {
    const todayStr = new Date().toISOString().slice(0, 10);
    const now = new Date().toISOString();
    // Capture ingredient prices at save time for Phase 5 price-change detection
    const ingredientPrices = data.ingredients.map(i => ({
      id: i.id,
      pack_price: i.pack_price,
      pack_quantity: i.pack_quantity,
    }));
    const snapshot = liveQ
      ? { ...JSON.parse(JSON.stringify(liveQ)), ingredient_prices: ingredientPrices }
      : null;
    const quoteToSave: SavedQuote = {
      id: activeSavedQuote?.id || (typeof crypto !== 'undefined' && crypto.randomUUID ? crypto.randomUUID() : `sq-${Date.now()}`),
      name: saveName.trim() || `Quote ${todayStr}`,
      created_at: activeSavedQuote?.created_at || now,
      updated_at: now,
      input: JSON.parse(JSON.stringify(quoteInput)),
      result_snapshot: snapshot,
      notes: saveNotes.trim() || undefined,
    };
    dispatch({ type: 'ADD_SAVED_QUOTE', item: quoteToSave });
    setShowSaveDialog(false);
  };

  return (
    <div>
      <div className="page-header">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="page-title gradient-text">Cake Quote</h1>
            <p className="page-subtitle">Configure your tiered cake and get an instant price</p>
          </div>
          {displayQ && (
            <div className="flex gap-8">
              <button className="btn btn-ghost btn-sm" onClick={copyText}>📋 Copy</button>
              <button className="btn btn-ghost btn-sm" onClick={() => window.print()}>🖨 Print</button>
              <button className="btn btn-secondary btn-sm" onClick={handleOpenSaveDialog}>💾 Save quote</button>
              <button className="btn btn-secondary btn-sm" onClick={() => dispatch({ type: 'RESET_QUOTE' })}>Reset</button>
              <button className="btn btn-primary btn-sm" onClick={() => setShowExplain(true)}>🔍 Explain</button>
            </div>
          )}
        </div>
      </div>

      {/* Banner if loaded from saved quote */}
      {activeSavedQuote && (
        <div
          className="saved-quote-banner"
          style={{
            background: 'rgba(167, 139, 250, 0.12)',
            border: '1px solid var(--accent)',
            borderRadius: 'var(--r-md)',
            padding: '12px 18px',
            marginBottom: 16,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'space-between',
            gap: 12,
            flexWrap: 'wrap',
          }}
        >
          <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
            <span style={{ fontSize: 20 }}>💾</span>
            <div>
              <div style={{ fontWeight: 600, fontSize: 14 }}>
                Loaded from saved quote: {activeSavedQuote.name} — {new Date(activeSavedQuote.created_at).toLocaleDateString()}
              </div>
              <div style={{ fontSize: 12, color: 'var(--text-secondary)' }}>
                {activeSavedQuote.isRecalculated
                  ? '⚡ Recalculated with current catalogue prices (snapshot unchanged).'
                  : '📌 Showing price snapshot from save time.'}
                {activeSavedQuote.notes ? ` • Note: ${activeSavedQuote.notes}` : ''}
              </div>
              {!activeSavedQuote.isRecalculated && priceChangedIngredients.length > 0 && (
                <div style={{ marginTop: 6, fontSize: 12, color: 'var(--accent-amber)', fontWeight: 500 }}>
                  ⚠ Ingredient prices have changed since this quote was saved: {priceChangedIngredients.join(', ')}
                </div>
              )}
            </div>
          </div>
          <div style={{ display: 'flex', gap: 8, alignItems: 'center' }}>
            {!activeSavedQuote.isRecalculated && (
              <button
                className="btn btn-secondary btn-sm"
                onClick={() => dispatch({ type: 'RECALCULATE_SAVED_QUOTE' })}
              >
                🔄 Recalculate with current prices
              </button>
            )}
            <button
              className="btn btn-ghost btn-sm"
              onClick={() => dispatch({ type: 'CLEAR_ACTIVE_SAVED_QUOTE' })}
              title="Close banner"
              aria-label="Close saved quote banner"
            >
              ✕
            </button>
          </div>
        </div>
      )}

      <div className="page-body" style={{ display: 'grid', gridTemplateColumns: '1fr 360px', gap: 20, alignItems: 'start' }}>
        {/* Left: configuration */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
          {/* Tiers */}
          <div className="card">
            <div className="card-header">
              <div>
                <div className="card-title">🎂 Tiers</div>
                <div className="card-subtitle">Tier 1 is required. Add up to 6 tiers.</div>
              </div>
              {activeTiers < 6 && (
                <button className="btn btn-secondary btn-sm" onClick={() => setActiveTiers(t => Math.min(t + 1, 6))}>
                  + Add tier
                </button>
              )}
            </div>
            <div className="tier-cards">
              {Array.from({ length: activeTiers }, (_, idx) => {
                const tier = quoteInput.tiers[idx];
                const res = displayQ?.tier_details?.[idx];
                const isActive = (tier.size_kg ?? 0) > 0;
                return (
                  <div key={idx} className={`tier-card ${isActive ? 'active' : ''}`}>
                    <div className="tier-card-header">
                      <span className="tier-label">Tier {idx + 1}{idx === 0 ? ' *' : ''}</span>
                      {isActive && res && (
                        <span className="badge badge-accent" style={{ fontSize: 11 }}>
                          {fmt(res.flavour_part + res.filling_part, cur)}
                        </span>
                      )}
                      {idx > 0 && (
                        <button className="btn btn-ghost btn-sm" onClick={() => {
                          updateTier(idx, { size_kg: 0, flavour_id: null, filling_id: null });
                          if (idx === activeTiers - 1) setActiveTiers(t => t - 1);
                        }} style={{ marginLeft: 'auto', padding: '3px 7px' }}>✕</button>
                      )}
                    </div>
                    <div className="form-row form-row-3" style={{ gap: 10 }}>
                      <div className="form-group">
                        <label>Size (kg)</label>
                        <NumberInput
                          value={tier.size_kg ?? 0}
                          onChange={v => updateTier(idx, { size_kg: v })}
                          step={0.1}
                          placeholder="kg"
                        />
                        {/* Size guide pills */}
                        {data.size_guide.length > 0 && (
                          <div className="size-guide-pills">
                            {data.size_guide.slice(0, 5).map(sg => (
                              <button
                                key={sg.label}
                                className="size-pill"
                                onClick={() => updateTier(idx, { size_kg: sg.kg })}
                                title={`${sg.label} — ${sg.servings} servings`}
                              >
                                {sg.label}
                              </button>
                            ))}
                          </div>
                        )}
                      </div>
                      <div className="form-group">
                        <label>Flavour</label>
                        <select
                          className="select"
                          value={tier.flavour_id ?? ''}
                          onChange={e => updateTier(idx, { flavour_id: e.target.value || null })}
                        >
                          <option value="">— pick flavour —</option>
                          {flavourOptions.map(f => (
                            <option key={f.id} value={f.id}>{f.name}</option>
                          ))}
                        </select>
                      </div>
                      <div className="form-group">
                        <label>Filling</label>
                        <select
                          className="select"
                          value={tier.filling_id ?? ''}
                          onChange={e => updateTier(idx, { filling_id: e.target.value || null })}
                        >
                          <option value="">— pick filling —</option>
                          {fillingOptions.map(f => (
                            <option key={f.id} value={f.id}>{f.name}</option>
                          ))}
                        </select>
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>

          {/* Decoration */}
          <div className="card">
            <div className="card-header">
              <div className="card-title">🎨 Decoration & Extras</div>
            </div>
            <div className="form-row form-row-3" style={{ gap: 12 }}>
              <div className="form-group">
                <label>Fondant (kg)</label>
                <NumberInput value={quoteInput.decoration.fondant_kg} onChange={v => updateDecoration('fondant_kg', v)} step={0.1} />
              </div>
              <div className="form-group">
                <label>Edible Prints (count)</label>
                <NumberInput value={quoteInput.decoration.prints} onChange={v => updateDecoration('prints', v)} />
              </div>
              <div className="form-group">
                <label>Flowers ({cur})</label>
                <NumberInput value={quoteInput.decoration.flowers} onChange={v => updateDecoration('flowers', v)} />
              </div>
              <div className="form-group">
                <label>Toppers (count)</label>
                <NumberInput value={quoteInput.decoration.toppers} onChange={v => updateDecoration('toppers', v)} />
              </div>
              <div className="form-group">
                <label>Time (hours)</label>
                <NumberInput value={quoteInput.decoration.time_hours} onChange={v => updateDecoration('time_hours', v)} step={0.5} />
                {quoteInput.decoration.time_hours === 0 && (
                  <span className="input-hint" style={{ color: 'var(--accent-amber)' }}>⚠ 0 hours = free labour</span>
                )}
              </div>
              <div className="form-group">
                <label>Other costs ({cur})</label>
                <NumberInput value={quoteInput.decoration.others} onChange={v => updateDecoration('others', v)} />
              </div>
              <div className="form-group">
                <label>Delivery ({cur})</label>
                <NumberInput value={quoteInput.decoration.delivery} onChange={v => updateDecoration('delivery', v)} />
                <span className="input-hint">No overhead/profit on delivery</span>
              </div>
              <div className="form-group" style={{ gridColumn: '1 / -1' }}>
                <label>Discount ({cur}) <span style={{ fontSize: 11, color: 'var(--text-muted)', fontWeight: 400 }}>— comes out of profit only</span></label>
                <div style={{ display: 'flex', gap: 6, alignItems: 'center', flexWrap: 'wrap' }}>
                  <div style={{ flex: '1 1 120px' }}>
                    <NumberInput
                      value={quoteInput.decoration.discount ?? 0}
                      onChange={v => updateDecoration('discount', Math.max(0, v))}
                      placeholder="0"
                    />
                  </div>
                  {/* Quick-fill buttons — render when displayQ exists */}
                  {displayQ && (
                    <>
                      <button className="btn btn-ghost btn-sm" onClick={() => updateDecoration('discount', 0)}>0</button>
                      <button className="btn btn-ghost btn-sm" onClick={() => updateDecoration('discount', parseFloat((displayQ.profit * 0.25).toFixed(2)))}>25%</button>
                      <button className="btn btn-ghost btn-sm" onClick={() => updateDecoration('discount', parseFloat((displayQ.profit * 0.50).toFixed(2)))}>50%</button>
                      <button className="btn btn-ghost btn-sm" onClick={() => updateDecoration('discount', parseFloat(displayQ.profit.toFixed(2)))} title="Sell at cost">100% (cost)</button>
                    </>
                  )}
                </div>
                {displayQ && displayQ.discount_capped && (
                  <span className="input-hint" style={{ color: 'var(--accent-amber)' }}>
                    ⚠ Capped to available profit ({fmt(displayQ.discount, cur)})
                  </span>
                )}
              </div>
            </div>
          </div>

          {/* Warnings */}
          {displayQ && displayQ.warnings.length > 0 && (
            <WarningsList warnings={displayQ.warnings} limit={5} />
          )}
        </div>

        {/* Right: results */}
        <div style={{ position: 'sticky', top: 80 }}>
          {!displayQ ? (
            <div className="card">
              <div className="empty-state">
                <div className="empty-state-icon">🎂</div>
                <div className="empty-state-title">Enter Tier 1 size</div>
                <div className="empty-state-text">Set a weight in Tier 1 to see pricing</div>
              </div>
            </div>
          ) : (
            <div className="card">
              <div className="results-big">
                <div className="text-secondary text-sm mb-4">TOTAL PRICE</div>
                <div className="money-xl">{fmt(displayQ.total_price, cur)}</div>
                {displayQ.suggested_price !== undefined && (
                  <div className="mt-4 suggested-price-line">
                    <span className="badge badge-amber" style={{ fontSize: 13, padding: '4px 10px' }}>
                      Suggested: {fmt(displayQ.suggested_price, cur)} (rounded to nearest {settings.price_rounding_step})
                    </span>
                  </div>
                )}
                <div className="mt-4 text-sm text-muted">
                  Margin {(displayQ.margin_check * 100).toFixed(1)}% · {displayQ.tiers_used} tier{displayQ.tiers_used !== 1 ? 's' : ''}
                </div>
              </div>

              <div className="result-row">
                <span className="result-row-label">Tier cost</span>
                <span className="money">{fmt(displayQ.tier_cost, cur)}</span>
              </div>
              <div className="result-row" style={{ paddingLeft: 12, fontSize: 12 }}>
                <span className="text-muted">Fondant</span>
                <span className="font-mono text-secondary">{fmt(displayQ.fondant, cur)}</span>
              </div>
              <div className="result-row" style={{ paddingLeft: 12, fontSize: 12 }}>
                <span className="text-muted">Print(s)</span>
                <span className="font-mono text-secondary">{fmt(displayQ.print, cur)}</span>
              </div>
              <div className="result-row" style={{ paddingLeft: 12, fontSize: 12 }}>
                <span className="text-muted">Flowers</span>
                <span className="font-mono text-secondary">{fmt(displayQ.flowers, cur)}</span>
              </div>
              <div className="result-row" style={{ paddingLeft: 12, fontSize: 12 }}>
                <span className="text-muted">Toppers</span>
                <span className="font-mono text-secondary">{fmt(displayQ.topper, cur)}</span>
              </div>
              <div className="result-row" style={{ paddingLeft: 12, fontSize: 12 }}>
                <span className="text-muted">Labour (time)</span>
                <span className="font-mono text-secondary">{fmt(displayQ.time, cur)}</span>
              </div>
              <div className="result-row" style={{ paddingLeft: 12, fontSize: 12 }}>
                <span className="text-muted">Others</span>
                <span className="font-mono text-secondary">{fmt(displayQ.others, cur)}</span>
              </div>
              <div className="result-row">
                <span className="result-row-label">Delivery</span>
                <span className="money">{fmt(displayQ.delivery, cur)}</span>
              </div>
              <div className="result-row">
                <span className="result-row-label">Overhead</span>
                <span className="money">{fmt(displayQ.overhead, cur)}</span>
              </div>
              <div className="result-row">
                <span className="result-row-label">Packaging</span>
                <span className="money">{fmt(displayQ.packaging, cur)}</span>
              </div>
              <div className="result-row result-row-total" style={{ padding: '12px 0', marginTop: 4, borderTop: '2px solid var(--border)' }}>
                <span>TOTAL COST</span>
                <span className="money">{fmt(displayQ.total_cost, cur)}</span>
              </div>
              <div className="result-row">
                <span className="result-row-label">Profit ({(settings.target_margin * 100).toFixed(0)}% margin)</span>
                <span className="money">{fmt(displayQ.profit, cur)}</span>
              </div>
              {displayQ.discount > 0 && (
                <div className="result-row" style={{ color: 'var(--accent-amber)' }}>
                  <span className="result-row-label">
                    Discount
                    {displayQ.discount_capped && (
                      <span style={{ fontSize: 11, marginLeft: 6, opacity: 0.8 }}>(capped to profit)</span>
                    )}
                  </span>
                  <span className="money">− {fmt(displayQ.discount, cur)}</span>
                </div>
              )}
              <div className="result-row" style={{ padding: '12px 0', marginTop: 4, borderTop: '2px solid var(--accent-dim)' }}>
                <span className="result-row-total" style={{ fontSize: 16 }}>TOTAL PRICE</span>
                <span className="result-row-price">{fmt(displayQ.total_price, cur)}</span>
              </div>
              {displayQ.suggested_price !== undefined && (
                <div
                  className="result-row suggested-price-row"
                  style={{ borderBottom: 'none', paddingBottom: 0, paddingTop: 4 }}
                >
                  <span className="text-muted text-sm">
                    Suggested (nearest {settings.price_rounding_step})
                  </span>
                  <span className="badge badge-amber" style={{ fontSize: 12 }}>
                    {fmt(displayQ.suggested_price, cur)}
                  </span>
                </div>
              )}
              {displayQ.suggested_price !== undefined && (
                <div style={{ fontSize: 11, color: 'var(--text-muted)', paddingBottom: 8, textAlign: 'right' }}>
                  Rounding is display-only — never used in calculations.
                </div>
              )}
              <div className="result-row" style={{ borderBottom: 'none' }}>
                <span className="text-muted text-sm">Margin check</span>
                <span className="badge badge-green">{(displayQ.margin_check * 100).toFixed(2)}%</span>
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Save Quote Dialog */}
      {showSaveDialog && (
        <div
          className="modal-overlay"
          style={{
            position: 'fixed',
            inset: 0,
            background: 'rgba(0, 0, 0, 0.7)',
            zIndex: 200,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            padding: 16,
          }}
          onClick={() => setShowSaveDialog(false)}
        >
          <div
            className="card"
            style={{ width: '100%', maxWidth: 440, background: 'var(--bg-card)' }}
            onClick={e => e.stopPropagation()}
          >
            <div className="card-header">
              <div className="card-title">💾 Save Quote</div>
              <button
                className="btn btn-ghost btn-sm"
                onClick={() => setShowSaveDialog(false)}
                aria-label="Close dialog"
              >
                ✕
              </button>
            </div>
            <div style={{ display: 'flex', flexDirection: 'column', gap: 14, marginTop: 12 }}>
              <div className="form-group">
                <label>Quote Name</label>
                <input
                  type="text"
                  className="input"
                  value={saveName}
                  onChange={e => setSaveName(e.target.value)}
                  placeholder={`Quote ${new Date().toISOString().slice(0, 10)}`}
                  autoFocus
                />
              </div>
              <div className="form-group">
                <label>Notes (optional)</label>
                <textarea
                  className="input"
                  rows={3}
                  value={saveNotes}
                  onChange={e => setSaveNotes(e.target.value)}
                  placeholder="e.g. Wedding cake for Sarah, floral theme..."
                />
              </div>
              <div style={{ display: 'flex', justifyContent: 'flex-end', gap: 10, marginTop: 8 }}>
                <button className="btn btn-secondary" onClick={() => setShowSaveDialog(false)}>
                  Cancel
                </button>
                <button className="btn btn-primary" onClick={handleSaveQuote}>
                  Save Quote
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {showExplain && displayQ && (
        <ExplainPanel
          title="Cake Quote"
          audit={displayQ.audit}
          currency={cur}
          onClose={() => setShowExplain(false)}
        />
      )}
    </div>
  );
}

import { useState, useMemo } from 'react';
import { useStore } from '../../store/store';
import type { Recipe, RecipeLine } from '../../engine/types';
import { compute } from '../../engine/engine';
import { NumberInput, SearchBar, ConfirmDialog } from '../components/Shared';
import { ExplainPanel } from '../components/ExplainPanel';
import { WarningsList } from '../components/WarningsList';

function generateId(existing: Recipe[]): string {
  const ids = new Set(existing.map(r => r.id));
  for (let i = 1; i < 9999; i++) {
    const id = `recipe_${i}`;
    if (!ids.has(id)) return id;
  }
  return 'recipe_' + Date.now();
}

function emptyLine(): RecipeLine {
  return { ingredient_id: null, quantity: 0, unit: 'g' };
}

const KIND_LABELS: Record<string, string> = {
  cake: '🎂 Cake',
  frosting_filling: '🧁 Frosting / Filling',
  batch_product: '🍩 Batch product',
  other: '📦 Other',
};

export function RecipesPage() {
  const { state, dispatch } = useStore();
  const { data } = state;
  const cur = data.settings.currency_code;

  const [search, setSearch] = useState('');
  const [kindFilter, setKindFilter] = useState<string>('all');
  const [editing, setEditing] = useState<Recipe | null>(null);
  const [isNew, setIsNew] = useState(false);
  const [deleteTarget, setDeleteTarget] = useState<Recipe | null>(null);
  const [explainTarget, setExplainTarget] = useState<Recipe | null>(null);
  const [scales, setScales] = useState<Record<string, number>>({});

  const baseResult = useMemo(() => compute(data), [data]);
  const result = useMemo(() => compute(data, null, scales), [data, scales]);

  const filtered = useMemo(() => data.recipes.filter(r => {
    const matchSearch = r.name.toLowerCase().includes(search.toLowerCase()) || r.id.includes(search.toLowerCase());
    const matchKind = kindFilter === 'all' || r.kind === kindFilter;
    return matchSearch && matchKind;
  }).sort((a, b) => a.name.localeCompare(b.name)), [data.recipes, search, kindFilter]);

  const openNew = () => {
    setIsNew(true);
    setEditing({
      id: generateId(data.recipes),
      name: '',
      kind: 'cake',
      lines: [emptyLine()],
      weight_adjustment_g: 0,
    });
  };

  const openEdit = (r: Recipe) => { setIsNew(false); setEditing(JSON.parse(JSON.stringify(r))); };

  const duplicate = (r: Recipe) => {
    setIsNew(true);
    setEditing({ ...JSON.parse(JSON.stringify(r)), id: generateId(data.recipes), name: r.name + ' (copy)' });
  };

  const save = () => {
    if (!editing || !editing.name.trim()) return;
    if (isNew) dispatch({ type: 'ADD_RECIPE', item: editing });
    else dispatch({ type: 'UPDATE_RECIPE', item: editing });
    setEditing(null);
  };

  const getUsedIn = (id: string) => {
    const used: string[] = [];
    for (const f of data.flavours) {
      if (f.cost_model.type === 'recipe') {
        if (f.cost_model.cake_recipe_id === id || f.cost_model.frosting_recipe_id === id) used.push(`Flavour: ${f.name}`);
      }
    }
    for (const fi of data.fillings) {
      if (fi.source.type === 'recipe' && fi.source.recipe_id === id) used.push(`Filling: ${fi.name}`);
    }
    for (const bp of data.batch_products) {
      if (bp.recipe_id === id) used.push(`Batch product: ${bp.name}`);
      if (bp.components.some(c => c.recipe_id === id)) used.push(`Batch product component: ${bp.name}`);
    }
    for (const ap of data.assembled_products) {
      if (ap.components.some(c => (c.type === 'cake_recipe_grams' || c.type === 'recipe_per_gram') && c.recipe_id === id)) {
        used.push(`Assembled product: ${ap.name}`);
      }
    }
    return used;
  };

  const confirmDelete = (r: Recipe) => {
    const used = getUsedIn(r.id);
    if (used.length > 0) { alert(`Cannot delete "${r.name}" — used in:\n${used.join('\n')}`); return; }
    setDeleteTarget(r);
  };

  // Editing helpers
  const updateLine = (idx: number, update: Partial<RecipeLine>) => {
    setEditing(r => {
      if (!r) return r;
      const lines = r.lines.map((l, i) => i === idx ? { ...l, ...update } : l);
      return { ...r, lines };
    });
  };

  const addLine = () => setEditing(r => r ? { ...r, lines: [...r.lines, emptyLine()] } : r);

  const removeLine = (idx: number) => setEditing(r => {
    if (!r) return r;
    return { ...r, lines: r.lines.filter((_, i) => i !== idx) };
  });

  const validUnitsForIng = (ingId: string | null): RecipeLine['unit'][] => {
    if (!ingId) return ['g'];
    const ing = data.ingredients.find(i => i.id === ingId);
    if (!ing) return ['g'];
    if (ing.unit_type === 'piece') return ['piece'];
    const units: RecipeLine['unit'][] = ['g'];
    if (ing.grams_per_tsp) units.push('tsp');
    return units;
  };

  return (
    <div>
      <div className="page-header">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="page-title">📋 Recipes</h1>
            <p className="page-subtitle">{data.recipes.length} recipes across {Object.keys(KIND_LABELS).length} types</p>
          </div>
          <button className="btn btn-primary btn-sm" onClick={openNew}>+ Add recipe</button>
        </div>
      </div>

      <div className="page-body">
        <div className="flex gap-12 items-center mb-12 flex-wrap">
          <SearchBar value={search} onChange={setSearch} placeholder="Search recipes…" />
          <div className="flex gap-4">
            {['all', ...Object.keys(KIND_LABELS)].map(k => (
              <button
                key={k}
                className={`btn btn-sm ${kindFilter === k ? 'btn-primary' : 'btn-ghost'}`}
                onClick={() => setKindFilter(k)}
              >
                {k === 'all' ? 'All' : KIND_LABELS[k]}
              </button>
            ))}
          </div>
        </div>

        {filtered.length === 0 ? (
          <div className="empty-state">
            <div className="empty-state-icon">📋</div>
            <div className="empty-state-title">No recipes yet</div>
            <button className="btn btn-primary mt-12" onClick={openNew}>+ Add recipe</button>
          </div>
        ) : (
          <div className="table-wrapper">
            <table>
              <thead>
                <tr>
                  <th>Name</th>
                  <th>Kind</th>
                  <th>Lines</th>
                  <th>Scale</th>
                  <th>Raw cost</th>
                  <th>CWO</th>
                  <th>Weight</th>
                  <th>Per gram</th>
                  <th>Cake /kg</th>
                  <th></th>
                </tr>
              </thead>
              <tbody>
                {filtered.map(r => {
                  const res = result.recipes[r.id];
                  const baseRes = baseResult.recipes[r.id];
                  const scale = scales[r.id] ?? 1;
                  return (
                    <tr key={r.id}>
                      <td>
                        <div style={{ fontWeight: 600 }}>{r.name}</div>
                        <div className="text-muted" style={{ fontSize: 11 }}>{r.id}</div>
                      </td>
                      <td><span className="badge badge-muted">{KIND_LABELS[r.kind]}</span></td>
                      <td className="text-secondary">{r.lines.length}</td>
                      <td>
                        <div style={{ width: 60 }}>
                          <NumberInput value={scale} onChange={v => setScales(s => ({ ...s, [r.id]: v }))} min={0} step={0.1} />
                        </div>
                      </td>
                      <td className="td-mono">
                        {scale !== 1 && <div className="text-muted" style={{ textDecoration: 'line-through', fontSize: 11 }}>{cur} {baseRes?.raw.toFixed(2)}</div>}
                        {cur} {res?.raw.toFixed(2) ?? '—'}
                      </td>
                      <td className="td-mono text-green">
                        {scale !== 1 && <div className="text-muted" style={{ textDecoration: 'line-through', fontSize: 11 }}>{cur} {baseRes?.cwo.toFixed(2)}</div>}
                        {cur} {res?.cwo.toFixed(2) ?? '—'}
                      </td>
                      <td className="td-mono">
                        {scale !== 1 && <div className="text-muted" style={{ textDecoration: 'line-through', fontSize: 11 }}>{baseRes?.weight.toFixed(0)}g</div>}
                        {res?.weight.toFixed(0) ?? '—'}g
                      </td>
                      <td className="td-mono">
                        {scale !== 1 && <div className="text-muted" style={{ textDecoration: 'line-through', fontSize: 11 }}>{cur} {baseRes?.per_gram_cwo.toFixed(4)}</div>}
                        {cur} {res?.per_gram_cwo.toFixed(4) ?? '—'}
                      </td>
                      <td className="td-mono text-green">
                        {scale !== 1 && <div className="text-muted" style={{ textDecoration: 'line-through', fontSize: 11 }}>{cur} {baseRes?.cake_cost_per_kg.toFixed(2)}</div>}
                        {cur} {res?.cake_cost_per_kg.toFixed(2) ?? '—'}
                      </td>
                      <td>
                        <div className="td-actions">
                          <button className="btn btn-ghost btn-sm" onClick={() => setExplainTarget(r)}>🔍</button>
                          <button className="btn btn-ghost btn-sm btn-icon" onClick={() => openEdit(r)}>✏️</button>
                          <button className="btn btn-ghost btn-sm btn-icon" onClick={() => duplicate(r)}>📋</button>
                          <button className="btn btn-danger btn-sm btn-icon" onClick={() => confirmDelete(r)}>🗑</button>
                        </div>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* Recipe editor modal */}
      {editing && (
        <div className="modal-backdrop" onClick={() => setEditing(null)}>
          <div className="modal modal-lg" onClick={e => e.stopPropagation()} style={{ maxWidth: 860 }}>
            <div className="modal-header">
              <h2 className="modal-title">{isNew ? 'New recipe' : `Edit: ${editing.name}`}</h2>
              <button className="btn btn-ghost btn-sm" onClick={() => setEditing(null)}>✕</button>
            </div>
            <div className="modal-body" style={{ display: 'grid', gridTemplateColumns: '1fr 260px', gap: 20 }}>
              {/* Left: recipe form */}
              <div style={{ display: 'flex', flexDirection: 'column', gap: 14 }}>
                <div className="form-row form-row-2">
                  <div className="form-group">
                    <label>Name *</label>
                    <input className="input" value={editing.name} onChange={e => setEditing(r => r && ({ ...r, name: e.target.value }))} />
                  </div>
                  <div className="form-group">
                    <label>Kind</label>
                    <select className="select" value={editing.kind} onChange={e => setEditing(r => r && ({ ...r, kind: e.target.value as Recipe['kind'] }))}>
                      {Object.entries(KIND_LABELS).map(([k, v]) => <option key={k} value={k}>{v}</option>)}
                    </select>
                  </div>
                </div>

                {/* Lines */}
                <div>
                  <div className="card-header" style={{ marginBottom: 8 }}>
                    <span className="card-title">Ingredients</span>
                    <button className="btn btn-secondary btn-sm" onClick={addLine}>+ Add line</button>
                  </div>
                  <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
                    {editing.lines.map((line, li) => {
                      const validUnits = validUnitsForIng(line.ingredient_id);
                      const curUnit = validUnits.includes(line.unit) ? line.unit : validUnits[0];
                      return (
                        <div key={li} style={{ display: 'grid', gridTemplateColumns: '1fr 80px 80px auto auto', gap: 6, alignItems: 'center' }}>
                          <select
                            className="select"
                            value={line.ingredient_id ?? ''}
                            onChange={e => {
                              const ingId = e.target.value || null;
                              const newUnits = validUnitsForIng(ingId);
                              updateLine(li, { ingredient_id: ingId, unit: newUnits[0] });
                            }}
                          >
                            <option value="">(free / water)</option>
                            {[...data.ingredients].sort((a, b) => a.name.localeCompare(b.name)).map(ing => <option key={ing.id} value={ing.id}>{ing.name}</option>)}
                          </select>
                          <NumberInput value={line.quantity} onChange={v => updateLine(li, { quantity: v })} placeholder="qty" />
                          <select
                            className="select"
                            value={curUnit}
                            onChange={e => updateLine(li, { unit: e.target.value as RecipeLine['unit'] })}
                          >
                            {validUnits.map(u => <option key={u} value={u}>{u}</option>)}
                          </select>
                          <button
                            className={`btn btn-sm ${line.exclude_from_weight ? 'btn-danger' : 'btn-ghost'}`}
                            onClick={() => updateLine(li, { exclude_from_weight: !line.exclude_from_weight })}
                            title="Exclude from batch weight"
                            style={{ fontSize: 11, padding: '4px 6px' }}
                          >⚖</button>
                          <button className="btn btn-danger btn-sm btn-icon" onClick={() => removeLine(li)}>✕</button>
                        </div>
                      );
                    })}
                  </div>
                </div>

                <div className="form-group">
                  <label>Weight adjustment (g)</label>
                  <NumberInput value={editing.weight_adjustment_g} onChange={v => setEditing(r => r && ({ ...r, weight_adjustment_g: v }))} allowNeg />
                  <span className="input-hint">Extra grams to add to batch weight (e.g. water, typed constants)</span>
                </div>

                <div className="form-group">
                  <label>Notes</label>
                  <input className="input" value={editing.notes ?? ''} onChange={e => setEditing(r => r && ({ ...r, notes: e.target.value }))} />
                </div>
              </div>

              {/* Right: live results */}
              <div>
                <div className="card" style={{ position: 'sticky', top: 0 }}>
                  <div className="card-title mb-12">Live results</div>
                  {(() => {
                    // Compute preview with current editing recipe
                    const previewData = { ...data, recipes: [...data.recipes.filter(r => r.id !== editing.id), editing] };
                    const res = compute(previewData).recipes[editing.id];
                    if (!res) return <div className="text-muted text-sm">Add lines to see results</div>;
                    return (
                      <div style={{ display: 'flex', flexDirection: 'column', gap: 8, fontSize: 13 }}>
                        <div className="result-row"><span className="text-secondary">Raw cost</span><span className="td-mono">{cur} {res.raw.toFixed(2)}</span></div>
                        <div className="result-row"><span className="text-secondary">CWO (+{(data.settings.overhead_pct * 100).toFixed(0)}%)</span><span className="td-mono text-green">{cur} {res.cwo.toFixed(2)}</span></div>
                        <div className="result-row"><span className="text-secondary">Batch weight</span><span className="td-mono">{res.weight.toFixed(0)}g</span></div>
                        <div className="result-row"><span className="text-secondary">Per gram</span><span className="td-mono">{cur} {res.per_gram_cwo.toFixed(5)}</span></div>
                        {editing.kind === 'cake' && <div className="result-row"><span className="text-secondary">Cake cost/kg</span><span className="td-mono text-green">{cur} {res.cake_cost_per_kg.toFixed(2)}</span></div>}
                        {editing.kind === 'frosting_filling' && <div className="result-row"><span className="text-secondary">Frosting/kg cake</span><span className="td-mono text-green">{cur} {res.frosting_cost_per_kg_cake.toFixed(2)}</span></div>}
                        {res.warnings.length > 0 && <WarningsList warnings={res.warnings} limit={3} />}
                      </div>
                    );
                  })()}
                </div>
              </div>
            </div>
            <div className="modal-footer">
              <button className="btn btn-ghost" onClick={() => setEditing(null)}>Cancel</button>
              <button className="btn btn-primary" onClick={save} disabled={!editing.name.trim()}>Save recipe</button>
            </div>
          </div>
        </div>
      )}

      {explainTarget && result.recipes[explainTarget.id] && (
        <ExplainPanel
          title={explainTarget.name}
          audit={result.recipes[explainTarget.id].audit}
          currency={cur}
          onClose={() => setExplainTarget(null)}
        />
      )}

      {deleteTarget && (
        <ConfirmDialog
          message={`Delete recipe "${deleteTarget.name}"?`}
          onConfirm={() => { dispatch({ type: 'DELETE_RECIPE', id: deleteTarget!.id }); setDeleteTarget(null); }}
          onCancel={() => setDeleteTarget(null)}
          confirmLabel="Delete"
          danger
        />
      )}
    </div>
  );
}

import { useState } from 'react';
import { useStore } from '../../store/store';
import type { SavedQuote } from '../../engine/types';

interface SavedQuotesPageProps {
  onNavigate: (page: string) => void;
}

function fmt(n: number, cur: string): string {
  return `${cur} ${n.toFixed(2)}`;
}

export function SavedQuotesPage({ onNavigate }: SavedQuotesPageProps) {
  const { state, dispatch } = useStore();
  const { saved_quotes, settings } = state.data;
  const cur = settings.currency_code;

  const [deleteTarget, setDeleteTarget] = useState<SavedQuote | null>(null);

  // Sort descending by created_at date
  const sortedQuotes = [...saved_quotes].sort((a, b) => {
    return new Date(b.created_at).getTime() - new Date(a.created_at).getTime();
  });

  const handleOpen = (quote: SavedQuote, recalculate = false) => {
    dispatch({ type: 'LOAD_SAVED_QUOTE', quote, recalculate });
    onNavigate('quote');
  };

  const confirmDelete = () => {
    if (!deleteTarget) return;
    dispatch({ type: 'DELETE_SAVED_QUOTE', id: deleteTarget.id });
    setDeleteTarget(null);
  };

  const getPrice = (q: SavedQuote): string => {
    const snap = q.result_snapshot as any;
    if (snap && typeof snap.total_price === 'number') {
      return fmt(snap.total_price, cur);
    }
    return '—';
  };

  const getTiersSummary = (q: SavedQuote): string => {
    const activeTiers = (q.input?.tiers || []).filter(t => (t.size_kg ?? 0) > 0);
    const count = activeTiers.length;
    if (count === 0) return '0 tiers';
    const totalKg = activeTiers.reduce((acc, t) => acc + (t.size_kg || 0), 0);
    return `${count} tier${count > 1 ? 's' : ''} (${totalKg.toFixed(1)} kg)`;
  };

  return (
    <div>
      <div className="page-header">
        <div className="flex items-center justify-between">
          <div>
            <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
              <h1 className="page-title gradient-text">Saved Quotes</h1>
              <span className="badge badge-accent" style={{ fontSize: 12 }}>
                {saved_quotes.length}
              </span>
            </div>
            <p className="page-subtitle">
              Browse, reopen, and recalculate your saved cake quotes with current prices
            </p>
          </div>
          <button
            className="btn btn-primary btn-sm"
            onClick={() => onNavigate('quote')}
          >
            + New Quote
          </button>
        </div>
      </div>

      <div className="page-body">
        {sortedQuotes.length === 0 ? (
          <div className="card" style={{ padding: '48px 24px', textAlign: 'center' }}>
            <div style={{ fontSize: 48, marginBottom: 16 }}>📋</div>
            <h3 style={{ fontSize: 18, marginBottom: 8, color: 'var(--text-primary)' }}>
              No saved quotes yet
            </h3>
            <p style={{ color: 'var(--text-secondary)', maxWidth: 460, margin: '0 auto 20px', fontSize: 13 }}>
              Configure a cake on the Quote page and click "Save quote" to snapshot it and revisit or recalculate later.
            </p>
            <button className="btn btn-primary" onClick={() => onNavigate('quote')}>
              Create Cake Quote
            </button>
          </div>
        ) : (
          <div className="card" style={{ padding: 0, overflow: 'hidden' }}>
            {/* Desktop Table View */}
            <div className="saved-quotes-table-container">
              <table className="table" style={{ width: '100%' }}>
                <thead>
                  <tr>
                    <th style={{ textAlign: 'left', padding: '14px 18px' }}>Quote Name</th>
                    <th style={{ textAlign: 'left', padding: '14px 18px' }}>Date Saved</th>
                    <th style={{ textAlign: 'left', padding: '14px 18px' }}>Tiers</th>
                    <th style={{ textAlign: 'right', padding: '14px 18px' }}>Saved Price</th>
                    <th style={{ textAlign: 'right', padding: '14px 18px' }}>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {sortedQuotes.map(sq => (
                    <tr
                      key={sq.id}
                      style={{
                        borderTop: '1px solid var(--border)',
                        transition: 'background 120ms ease',
                      }}
                    >
                      <td style={{ padding: '14px 18px' }}>
                        <div
                          style={{
                            fontWeight: 600,
                            color: 'var(--text-primary)',
                            cursor: 'pointer',
                          }}
                          onClick={() => handleOpen(sq, false)}
                          title="Click to open quote"
                        >
                          {sq.name}
                        </div>
                        {sq.notes && (
                          <div style={{ fontSize: 12, color: 'var(--text-muted)', marginTop: 2 }}>
                            {sq.notes}
                          </div>
                        )}
                      </td>
                      <td style={{ padding: '14px 18px', color: 'var(--text-secondary)', fontSize: 13, whiteSpace: 'nowrap' }}>
                        {new Date(sq.created_at).toLocaleDateString(undefined, {
                          year: 'numeric',
                          month: 'short',
                          day: 'numeric',
                        })}
                      </td>
                      <td style={{ padding: '14px 18px', color: 'var(--text-secondary)', fontSize: 13 }}>
                        {getTiersSummary(sq)}
                      </td>
                      <td style={{ padding: '14px 18px', textAlign: 'right', fontWeight: 600, color: 'var(--accent)', fontVariantNumeric: 'tabular-nums' }}>
                        {getPrice(sq)}
                      </td>
                      <td style={{ padding: '14px 18px', textAlign: 'right', whiteSpace: 'nowrap' }}>
                        <div style={{ display: 'flex', gap: 8, justifyContent: 'flex-end', alignItems: 'center' }}>
                          <button
                            className="btn btn-secondary btn-sm"
                            onClick={() => handleOpen(sq, false)}
                            title="Open quote with saved price snapshot"
                          >
                            Open
                          </button>
                          <button
                            className="btn btn-primary btn-sm"
                            onClick={() => handleOpen(sq, true)}
                            title="Recalculate this quote with current catalogue prices"
                          >
                            🔄 Recalculate
                          </button>
                          <button
                            className="btn btn-ghost btn-sm"
                            style={{ color: 'var(--accent-red)' }}
                            onClick={() => setDeleteTarget(sq)}
                            title="Delete quote"
                            aria-label={`Delete quote ${sq.name}`}
                          >
                            🗑
                          </button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>

            {/* Mobile Card List View */}
            <div className="saved-quotes-cards-container">
              {sortedQuotes.map(sq => (
                <div
                  key={sq.id}
                  className="saved-quote-card"
                  style={{
                    padding: '16px',
                    borderBottom: '1px solid var(--border)',
                    display: 'flex',
                    flexDirection: 'column',
                    gap: 10,
                  }}
                >
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', gap: 8 }}>
                    <div>
                      <div
                        style={{ fontWeight: 600, fontSize: 15, color: 'var(--text-primary)', cursor: 'pointer' }}
                        onClick={() => handleOpen(sq, false)}
                      >
                        {sq.name}
                      </div>
                      <div style={{ fontSize: 12, color: 'var(--text-muted)', marginTop: 2 }}>
                        {new Date(sq.created_at).toLocaleDateString(undefined, {
                          year: 'numeric',
                          month: 'short',
                          day: 'numeric',
                        })} • {getTiersSummary(sq)}
                      </div>
                    </div>
                    <div style={{ textAlign: 'right' }}>
                      <div style={{ fontSize: 15, fontWeight: 700, color: 'var(--accent)', fontVariantNumeric: 'tabular-nums' }}>
                        {getPrice(sq)}
                      </div>
                      <span className="badge badge-secondary" style={{ fontSize: 10 }}>Saved Price</span>
                    </div>
                  </div>

                  {sq.notes && (
                    <div style={{ fontSize: 12, color: 'var(--text-secondary)', background: 'var(--bg-surface)', padding: '6px 10px', borderRadius: 'var(--r-sm)' }}>
                      {sq.notes}
                    </div>
                  )}

                  <div style={{ display: 'flex', gap: 8, marginTop: 4 }}>
                    <button
                      className="btn btn-secondary btn-sm"
                      style={{ flex: 1 }}
                      onClick={() => handleOpen(sq, false)}
                    >
                      Open
                    </button>
                    <button
                      className="btn btn-primary btn-sm"
                      style={{ flex: 1 }}
                      onClick={() => handleOpen(sq, true)}
                    >
                      🔄 Recalculate
                    </button>
                    <button
                      className="btn btn-ghost btn-sm"
                      style={{ color: 'var(--accent-red)' }}
                      onClick={() => setDeleteTarget(sq)}
                      aria-label={`Delete quote ${sq.name}`}
                    >
                      🗑
                    </button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>

      {/* Delete Confirmation Dialog */}
      {deleteTarget && (
        <div
          className="modal-overlay"
          style={{
            position: 'fixed',
            inset: 0,
            background: 'rgba(0, 0, 0, 0.7)',
            zIndex: 200,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            padding: 16,
          }}
          onClick={() => setDeleteTarget(null)}
        >
          <div
            className="card"
            style={{ width: '100%', maxWidth: 400, background: 'var(--bg-card)' }}
            onClick={e => e.stopPropagation()}
          >
            <div className="card-header">
              <div className="card-title">Delete Saved Quote?</div>
              <button className="btn btn-ghost btn-sm" onClick={() => setDeleteTarget(null)}>✕</button>
            </div>
            <p style={{ fontSize: 13, color: 'var(--text-secondary)', margin: '12px 0 20px' }}>
              Are you sure you want to delete <strong>"{deleteTarget.name}"</strong>? This action cannot be undone.
            </p>
            <div style={{ display: 'flex', justifyContent: 'flex-end', gap: 10 }}>
              <button className="btn btn-secondary" onClick={() => setDeleteTarget(null)}>
                Cancel
              </button>
              <button
                className="btn btn-primary"
                style={{ background: 'var(--accent-red)', borderColor: 'var(--accent-red)' }}
                onClick={confirmDelete}
              >
                Delete Quote
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import { useState } from 'react';
import type { FormEvent } from 'react';
import { useStore } from '../../store/store';
import type { Settings, SizeGuideEntry } from '../../engine/types';
import { NumberInput } from '../components/Shared';

export function SettingsPage() {
  const { state, dispatch } = useStore();
  const { settings, ingredients, packaging_items, size_guide } = state.data;
  const sortedIngredients = [...ingredients].sort((a, b) => a.name.localeCompare(b.name));
  const sortedPackaging = [...packaging_items].sort((a, b) => a.name.localeCompare(b.name));
  const [localSettings, setLocalSettings] = useState<Settings>({ ...settings });
  const [localSizeGuide, setLocalSizeGuide] = useState<SizeGuideEntry[]>([...size_guide]);
  const [draggedSgIndex, setDraggedSgIndex] = useState<number | null>(null);
  const [savedMsg, setSavedMsg] = useState(false);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);

  const handleChange = <K extends keyof Settings>(key: K, value: Settings[K]) => {
    setLocalSettings(prev => ({ ...prev, [key]: value }));
    setErrorMsg(null);
  };

  const handleSave = (e: FormEvent) => {
    e.preventDefault();

    // Validation: margin must be < 1 (100%)
    if (localSettings.target_margin >= 1) {
      setErrorMsg('Target margin must be less than 100% (less than 1.0). A margin of 100% or greater is mathematically impossible for gross margin pricing.');
      return;
    }
    if (localSettings.target_margin < 0) {
      setErrorMsg('Target margin cannot be negative.');
      return;
    }
    if (localSettings.overhead_pct < 0) {
      setErrorMsg('Overhead percentage cannot be negative.');
      return;
    }
    if (localSettings.labour_rate_per_hour < 0) {
      setErrorMsg('Labour rate cannot be negative.');
      return;
    }

    dispatch({ type: 'SET_SETTINGS', settings: localSettings });
    dispatch({ type: 'SET_SIZE_GUIDE', guide: localSizeGuide });
    setSavedMsg(true);
    setTimeout(() => setSavedMsg(false), 2500);
  };

  return (
    <div className="card" style={{ maxWidth: 840, margin: '0 auto' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 20 }}>
        <div>
          <h2>System Settings</h2>
          <div style={{ color: 'var(--text-muted)', fontSize: 13, marginTop: 4 }}>
            Configure global labor rates, overhead multipliers, target margins, batch factors, and role mappings.
          </div>
        </div>
        {savedMsg && <span className="badge badge-success" style={{ padding: '6px 12px' }}>✓ Settings Saved</span>}
      </div>

      {errorMsg && (
        <div className="error-banner" style={{ marginBottom: 16 }}>
          ⚠️ {errorMsg}
        </div>
      )}

      <form onSubmit={handleSave}>
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(360px, 1fr))', gap: 20 }}>
          {/* Financial & Rates Block */}
          <div className="card" style={{ background: 'var(--bg-surface)' }}>
            <h3 style={{ fontSize: 16, marginBottom: 14, color: 'var(--accent)' }}>Pricing & Economics</h3>

            <div style={{ marginBottom: 14 }}>
              <label style={{ display: 'block', fontSize: 13, fontWeight: 500, marginBottom: 4 }}>Currency Code</label>
              <input
                type="text"
                className="input"
                style={{ width: '100%' }}
                value={localSettings.currency_code}
                onChange={e => handleChange('currency_code', e.target.value)}
                placeholder="BDT, USD, EUR..."
                required
              />
              <span style={{ fontSize: 11, color: 'var(--text-muted)' }}>Symbol or ISO code displayed next to all monetary amounts.</span>
            </div>

            <div style={{ marginBottom: 14 }}>
              <label style={{ display: 'block', fontSize: 13, fontWeight: 500, marginBottom: 4 }}>Labour Rate per Hour</label>
              <NumberInput
                value={localSettings.labour_rate_per_hour}
                onChange={v => handleChange('labour_rate_per_hour', v)}
                step={1}
                min={0}
              />
              <span style={{ fontSize: 11, color: 'var(--text-muted)' }}>Standard hourly rate for bakery decoration and prep labour.</span>
            </div>

            <div style={{ marginBottom: 14 }}>
              <label style={{ display: 'block', fontSize: 13, fontWeight: 500, marginBottom: 4 }}>
                Overhead Percentage (e.g. 0.25 for 25%)
              </label>
              <NumberInput
                value={localSettings.overhead_pct}
                onChange={v => handleChange('overhead_pct', v)}
                step={0.01}
                min={0}
              />
              <span style={{ fontSize: 11, color: 'var(--text-muted)' }}>
                Applied once per cost: raw recipe cost, decoration sum, and bought fillings.
                <br />
                <em>Note: Applied once per cost; see the Explain view.</em>
              </span>
            </div>

            <div style={{ marginBottom: 14 }}>
              <label style={{ display: 'block', fontSize: 13, fontWeight: 500, marginBottom: 4 }}>
                Target Gross Margin (e.g. 0.30 for 30%)
              </label>
              <NumberInput
                value={localSettings.target_margin}
                onChange={v => handleChange('target_margin', v)}
                step={0.01}
                min={0}
                max={0.999}
              />
              <span style={{ fontSize: 11, color: 'var(--text-muted)' }}>
                Target profit margin on non-delivery revenue: Profit = (Cost - Delivery) × Margin / (1 - Margin). Must be &lt; 1.0 (100%).
              </span>
            </div>

            <div style={{ marginBottom: 14 }}>
              <label style={{ display: 'block', fontSize: 13, fontWeight: 500, marginBottom: 4 }}>
                Packaging Allowance (e.g. 0.20 for 20%)
              </label>
              <NumberInput
                value={localSettings.packaging_allowance_pct}
                onChange={v => handleChange('packaging_allowance_pct', v)}
                step={0.01}
                min={0}
              />
              <span style={{ fontSize: 11, color: 'var(--text-muted)' }}>Contingency buffer percentage applied to total packaging costs.</span>
            </div>

            <div style={{ marginBottom: 14 }}>
              <label style={{ display: 'block', fontSize: 13, fontWeight: 500, marginBottom: 4 }}>Standard Topper Price</label>
              <NumberInput
                value={localSettings.topper_price}
                onChange={v => handleChange('topper_price', v)}
                step={1}
                min={0}
              />
              <span style={{ fontSize: 11, color: 'var(--text-muted)' }}>Default price charged per standard acrylic/paper cake topper.</span>
            </div>

            <div style={{ marginBottom: 14 }}>
              <label style={{ display: 'block', fontSize: 13, fontWeight: 500, marginBottom: 4 }}>Price Rounding Step (0 = Off)</label>
              <NumberInput
                value={localSettings.price_rounding_step ?? 0}
                onChange={v => handleChange('price_rounding_step', v)}
                step={1}
                min={0}
              />
              <span style={{ fontSize: 11, color: 'var(--text-muted)' }}>
                When &gt; 0 (e.g. 10 or 50), shows suggested rounded selling prices alongside exact prices.
                <br />
                <span style={{ color: 'var(--text-secondary)' }}>Note: Rounding is display-only and never used in calculations.</span>
              </span>
            </div>
          </div>

          {/* Cake Engineering & Ratios */}
          <div className="card" style={{ background: 'var(--bg-surface)' }}>
            <h3 style={{ fontSize: 16, marginBottom: 14, color: 'var(--accent)' }}>Cake Engineering Factors</h3>

            <div style={{ marginBottom: 14 }}>
              <label style={{ display: 'block', fontSize: 13, fontWeight: 500, marginBottom: 4 }}>Cake Batches per kg of Cake</label>
              <NumberInput
                value={localSettings.cake_batches_per_kg}
                onChange={v => handleChange('cake_batches_per_kg', v)}
                step={0.05}
                min={0.01}
              />
              <span style={{ fontSize: 11, color: 'var(--text-muted)' }}>
                Number of sponge batches needed to yield 1 kg of finished cake (default: 1.0).
              </span>
            </div>

            <div style={{ marginBottom: 14 }}>
              <label style={{ display: 'block', fontSize: 13, fontWeight: 500, marginBottom: 4 }}>Frosting Batches per kg of Cake</label>
              <NumberInput
                value={localSettings.frosting_batches_per_kg}
                onChange={v => handleChange('frosting_batches_per_kg', v)}
                step={0.05}
                min={0.01}
              />
              <span style={{ fontSize: 11, color: 'var(--text-muted)' }}>
                Number of frosting batches needed to cover/crumb coat 1 kg of cake (default: 1.25).
              </span>
            </div>

            <div style={{ marginBottom: 14 }}>
              <label style={{ display: 'block', fontSize: 13, fontWeight: 500, marginBottom: 4 }}>Filling Grams per kg of Cake</label>
              <NumberInput
                value={localSettings.filling_grams_per_kg}
                onChange={v => handleChange('filling_grams_per_kg', v)}
                step={1}
                min={0}
              />
              <span style={{ fontSize: 11, color: 'var(--text-muted)' }}>
                Standard weight in grams of filling used per 1 kg of layered cake (default: 150g).
              </span>
            </div>

            <h3 style={{ fontSize: 16, marginTop: 24, marginBottom: 14, color: 'var(--accent)' }}>Role Mappings</h3>
            <div style={{ fontSize: 12, color: 'var(--text-muted)', marginBottom: 12 }}>
              Map generic quote roles (fondant, edible print, boards, boxes) to specific items in your catalog.
            </div>

            <div style={{ marginBottom: 12 }}>
              <label style={{ display: 'block', fontSize: 13, fontWeight: 500, marginBottom: 4 }}>Fondant Ingredient</label>
              <select
                className="select"
                style={{ width: '100%' }}
                value={localSettings.fondant_ingredient_id ?? ''}
                onChange={e => handleChange('fondant_ingredient_id', e.target.value || null)}
              >
                <option value="">(None selected)</option>
                {sortedIngredients.map(ing => (
                  <option key={ing.id} value={ing.id}>{ing.name} ({ing.unit_type})</option>
                ))}
              </select>
            </div>

            <div style={{ marginBottom: 12 }}>
              <label style={{ display: 'block', fontSize: 13, fontWeight: 500, marginBottom: 4 }}>Edible Print Item</label>
              <select
                className="select"
                style={{ width: '100%' }}
                value={localSettings.edible_print_item_id ?? ''}
                onChange={e => handleChange('edible_print_item_id', e.target.value || null)}
              >
                <option value="">(None selected)</option>
                {sortedPackaging.map(p => (
                  <option key={p.id} value={p.id}>{p.name}</option>
                ))}
              </select>
            </div>

            <div style={{ marginBottom: 12 }}>
              <label style={{ display: 'block', fontSize: 13, fontWeight: 500, marginBottom: 4 }}>Standard Cake Box</label>
              <select
                className="select"
                style={{ width: '100%' }}
                value={localSettings.cake_box_item_id ?? ''}
                onChange={e => handleChange('cake_box_item_id', e.target.value || null)}
              >
                <option value="">(None selected)</option>
                {sortedPackaging.map(p => (
                  <option key={p.id} value={p.id}>{p.name}</option>
                ))}
              </select>
            </div>

            <div style={{ marginBottom: 12 }}>
              <label style={{ display: 'block', fontSize: 13, fontWeight: 500, marginBottom: 4 }}>MDF Drum Board</label>
              <select
                className="select"
                style={{ width: '100%' }}
                value={localSettings.mdf_board_item_id ?? ''}
                onChange={e => handleChange('mdf_board_item_id', e.target.value || null)}
              >
                <option value="">(None selected)</option>
                {sortedPackaging.map(p => (
                  <option key={p.id} value={p.id}>{p.name}</option>
                ))}
              </select>
            </div>

            <div style={{ marginBottom: 12 }}>
              <label style={{ display: 'block', fontSize: 13, fontWeight: 500, marginBottom: 4 }}>Standard Cake Board (per extra tier)</label>
              <select
                className="select"
                style={{ width: '100%' }}
                value={localSettings.standard_board_item_id ?? ''}
                onChange={e => handleChange('standard_board_item_id', e.target.value || null)}
              >
                <option value="">(None selected)</option>
                {sortedPackaging.map(p => (
                  <option key={p.id} value={p.id}>{p.name}</option>
                ))}
              </select>
            </div>

            <div style={{ marginBottom: 12 }}>
              <label style={{ display: 'block', fontSize: 13, fontWeight: 500, marginBottom: 4 }}>Wallpaper / Cake Wrap</label>
              <select
                className="select"
                style={{ width: '100%' }}
                value={localSettings.wallpaper_item_id ?? ''}
                onChange={e => handleChange('wallpaper_item_id', e.target.value || null)}
              >
                <option value="">(None selected)</option>
                {sortedPackaging.map(p => (
                  <option key={p.id} value={p.id}>{p.name}</option>
                ))}
              </select>
            </div>
          </div>
        </div>

        {/* Size Guide */}
        <div className="card" style={{ background: 'var(--bg-surface)', marginTop: 20 }}>
          <h3 style={{ fontSize: 16, marginBottom: 14, color: 'var(--accent)' }}>Size Guide</h3>
          <div style={{ fontSize: 13, color: 'var(--text-muted)', marginBottom: 16 }}>
            Define the pan sizes available when building a quote tier. Drag the handle to reorder.
          </div>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
            {localSizeGuide.map((sg, idx) => (
              <div 
                key={idx} 
                draggable
                onDragStart={e => { setDraggedSgIndex(idx); e.dataTransfer.effectAllowed = 'move'; }}
                onDragOver={e => e.preventDefault()}
                onDrop={e => {
                  e.preventDefault();
                  if (draggedSgIndex === null || draggedSgIndex === idx) return;
                  const newG = [...localSizeGuide];
                  const [m] = newG.splice(draggedSgIndex, 1);
                  newG.splice(idx, 0, m);
                  setLocalSizeGuide(newG);
                  setDraggedSgIndex(null);
                }}
                style={{ 
                  display: 'flex', gap: 12, alignItems: 'center', background: 'var(--bg-card)', 
                  padding: '12px', borderRadius: 'var(--r-md)', border: '1px solid var(--border)' 
                }}
              >
                <div style={{ cursor: 'grab', opacity: 0.5 }}>☰</div>
                <div className="form-row form-row-3" style={{ flex: 1, gap: 12, marginBottom: 0 }}>
                  <div className="form-group" style={{ marginBottom: 0 }}>
                    <label>Label</label>
                    <input type="text" className="input" style={{ width: '100%' }} value={sg.label} onChange={e => {
                      const newG = [...localSizeGuide];
                      newG[idx].label = e.target.value;
                      setLocalSizeGuide(newG);
                    }} placeholder='e.g. 5"' required />
                  </div>
                  <div className="form-group" style={{ marginBottom: 0 }}>
                    <label>Weight (kg)</label>
                    <NumberInput value={sg.kg} onChange={v => {
                      const newG = [...localSizeGuide];
                      newG[idx].kg = v;
                      setLocalSizeGuide(newG);
                    }} step={0.1} min={0} />
                  </div>
                  <div className="form-group" style={{ marginBottom: 0 }}>
                    <label>Servings</label>
                    <NumberInput value={sg.servings} onChange={v => {
                      const newG = [...localSizeGuide];
                      newG[idx].servings = v;
                      setLocalSizeGuide(newG);
                    }} step={1} min={0} />
                  </div>
                </div>
                <button type="button" className="btn btn-ghost btn-sm btn-icon text-danger" onClick={() => {
                  setLocalSizeGuide(g => g.filter((_, i) => i !== idx));
                }}>✕</button>
              </div>
            ))}
          </div>
          <button type="button" className="btn btn-secondary btn-sm mt-4" onClick={() => {
            setLocalSizeGuide(g => [...g, { label: '', kg: 0, servings: 0 }]);
          }}>+ Add Size</button>
        </div>

        <div style={{ marginTop: 24, display: 'flex', justifyContent: 'flex-end', gap: 12 }}>
          <button type="button" className="btn btn-secondary" onClick={() => { setLocalSettings({ ...settings }); setLocalSizeGuide([...size_guide]); }}>
            Discard Changes
          </button>
          <button type="submit" className="btn btn-primary">
            Save Settings
          </button>
        </div>
      </form>
    </div>
  );
}

